window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-1/physiologie","titre":"Physiologie I","sources":[{"t":"Physio I — Histologie animale","q":"qcm/qcm-1-histologie-animale.html","f":"fiches/fiche-1-histologie-animale.html"},{"t":"Physio I — Système tégumentaire","q":"qcm/qcm-2-systeme-tegumentaire.html","f":"fiches/fiche-2-systeme-tegumentaire.html"},{"t":"Physio I — Physiologie des membranes","q":"qcm/qcm-3-physiologie-membranes.html","f":"fiches/fiche-3-physiologie-membranes.html"},{"t":"Physio I — Système nerveux","q":"qcm/qcm-4-systeme-nerveux.html","f":"fiches/fiche-4-systeme-nerveux.html"},{"t":"Physio I — Système endocrinien","q":"qcm/qcm-5-systeme-endocrinien.html","f":"fiches/fiche-5-systeme-endocrinien.html"},{"t":"Physio I — Système cardiovasculaire","q":"qcm/qcm-6-systeme-cardiovasculaire.html","f":"fiches/fiche-6-systeme-cardiovasculaire.html"},{"t":"Physio I — Système lymphatique","q":"qcm/qcm-7-systeme-lymphatique.html","f":"fiches/fiche-7-systeme-lymphatique.html"},{"t":"Physio I — Système respiratoire","q":"qcm/qcm-8-systeme-respiratoire.html","f":"fiches/fiche-8-systeme-respiratoire.html"}],"questions":[{"q":"Qui a énoncé en 1858 que « chaque animal représente la somme d'unités vitales » ?","o":["Pasteur","Rudolf Virchow","Robert Hooke","Schleiden"],"r":1,"e":"Rudolf Virchow (1858) a complété la théorie cellulaire.","s":0},{"q":"Pourquoi la plupart des cellules sont-elles petites ?","o":["Pour résister à la pression","Pour mieux se diviser","Le rapport surface/volume diminue quand la taille augmente","Pour économiser de l'ADN"],"r":2,"e":"Une grande cellule a une surface relative plus faible → échanges moins efficaces.","s":0},{"q":"Quelle est la principale différence entre procaryotes et eucaryotes ?","o":["La présence d'ADN","La présence d'un noyau et de membranes internes chez les eucaryotes","La taille","La présence de ribosomes"],"r":1,"e":"Les eucaryotes possèdent un noyau délimité et des organites membranaires → compartimentation.","s":0},{"q":"Quel est le rôle clé de la compartimentation cellulaire ?","o":["Augmenter la vitesse de division","Séparer des réactions chimiques différentes","Diminuer l'énergie","Augmenter la taille de la cellule"],"r":1,"e":"La compartimentation organise les réactions chimiques incompatibles dans des organites séparés.","s":0},{"q":"Lequel ne fait PAS partie du système membranaire de la cellule ?","o":["Réticulum endoplasmique","Complexe de Golgi","Mitochondrie","Membrane nucléaire"],"r":2,"e":"La mitochondrie ne fait pas partie du système membranaire endomembranaire (RE, Golgi, vésicules, lysosomes, membrane nucléaire et plasmique).","s":0},{"q":"La phagocytose concerne :","o":["Des particules dissoutes en liquide","Des particules solides (bactéries, débris)","Uniquement les hormones","Les sels minéraux"],"r":1,"e":"La phagocytose ingère des particules SOLIDES comme les bactéries ou débris cellulaires.","s":0},{"q":"Comment se fait l'exocytose ?","o":["Par diffusion passive","Par fusion de vésicules sécrétoires avec la membrane plasmique","Par invagination de la membrane","Par destruction de la membrane"],"r":1,"e":"Les vésicules sécrétoires fusionnent avec la membrane plasmique et libèrent leur contenu.","s":0},{"q":"Quel ARN apporte les acides aminés au ribosome ?","o":["ARNm","ARNr","ARNt","ARNsi"],"r":2,"e":"L'ARN de transfert (ARNt) transporte les acides aminés jusqu'au ribosome.","s":0},{"q":"Sur le ribosome, le site P contient :","o":["L'acide aminé entrant","Le polypeptide en croissance","L'ARNm","L'ADN"],"r":1,"e":"Site P = polypeptide ; Site A = acide aminé entrant.","s":0},{"q":"À quelle phase du cycle cellulaire se fait la réplication de l'ADN ?","o":["G1","S","G2","Mitose"],"r":1,"e":"La phase S (synthèse) correspond à la réplication de l'ADN.","s":0},{"q":"Combien de cellules filles résultent d'une méiose ?","o":["2 diploïdes","2 haploïdes","4 haploïdes","4 diploïdes"],"r":2,"e":"La méiose produit 4 cellules haploïdes génétiquement différentes.","s":0},{"q":"Quelle caractéristique n'appartient PAS au tissu épithélial ?","o":["Absence de substance interstitielle","Présence d'une membrane basale","Vascularisation abondante","Jonctions intercellulaires"],"r":2,"e":"Le tissu épithélial est AVASCULAIRE (pas de vaisseaux sanguins).","s":0},{"q":"Quelles jonctions permettent un courant électrique entre cellules ?","o":["Jonctions occlusives","Jonctions communicantes (gap)","Desmosomes","Hémidesmosomes"],"r":1,"e":"Les jonctions Gap permettent le passage ionique → synapses électriques (cœur, intestin).","s":0},{"q":"Dans un desmosome de cellule épithéliale, quels filaments intermédiaires sont impliqués ?","o":["Actine","Myosine","Kératine","Tubuline"],"r":2,"e":"Les kératines sont associées aux desmosomes des cellules épithéliales ; la desmine est dans le muscle cardiaque.","s":0},{"q":"Quel épithélium recouvre les bronches ?","o":["Simple pavé","Stratifié pavé kératinisé","Pseudo-stratifié cylindrique cilié","De transition"],"r":2,"e":"L'épithélium pseudo-stratifié cylindrique cilié tapisse les bronches.","s":0},{"q":"L'épithélium de transition (urothélium) se trouve dans :","o":["L'œsophage","Le tractus urinaire (vessie, uretères)","Les bronches","Les alvéoles"],"r":1,"e":"L'urothélium s'adapte à la distension de la vessie et des uretères.","s":0},{"q":"Quelle est la cellule la plus courante du tissu conjonctif ?","o":["Macrophage","Mastocyte","Fibroblaste","Plasmocyte"],"r":2,"e":"Les fibroblastes synthétisent les fibres et la substance interstitielle.","s":0},{"q":"Le tissu adipeux multiloculaire (brun) a pour fonction principale :","o":["Réserve énergétique","Production de chaleur (thermogenèse)","Soutien mécanique","Synthèse hormonale"],"r":1,"e":"Multiloculaire = nombreuses vacuoles + mitochondries → conversion d'énergie chimique en chaleur.","s":0},{"q":"Quelle cellule détruit (résorbe) la matrice osseuse ?","o":["Ostéoblaste","Ostéocyte","Ostéoclaste","Chondrocyte"],"r":2,"e":"Les ostéoclastes résorbent l'os ; les ostéoblastes le construisent ; les ostéocytes l'entretiennent.","s":0},{"q":"Quel type de collagène domine la matrice osseuse ?","o":["Type I","Type II","Type III","Type IV"],"r":0,"e":"Le collagène de type I est majoritaire dans l'os (et dans le derme, tendons).","s":0},{"q":"Caractéristique propre au muscle squelettique :","o":["Cellules fusiformes uninucléées","Cellules allongées multinucléées à noyaux périphériques","Cellules ramifiées binucléées centrales","Fibres non striées"],"r":1,"e":"Le muscle squelettique = fibres striées allongées multinucléées avec noyaux en périphérie.","s":0},{"q":"Le sarcomère est défini comme :","o":["L'espace entre deux bandes A","L'espace entre deux lignes Z","La totalité de la fibre","L'enveloppe du muscle"],"r":1,"e":"Le sarcomère = unité contractile minimale, s'étend d'une ligne Z à la suivante (≈ 2,5 µm au repos).","s":0},{"q":"Lequel n'est PAS un filament fin ?","o":["Actine","Tropomyosine","Troponine","Myosine"],"r":3,"e":"La myosine constitue les filaments ÉPAIS ; actine, tropomyosine et troponine sont les filaments fins.","s":0},{"q":"Les disques intercalaires sont caractéristiques :","o":["Du muscle squelettique","Du muscle cardiaque","Du muscle lisse","Du tissu nerveux"],"r":1,"e":"Les disques intercalaires relient les cellules musculaires cardiaques (jonctions adhérentes + gap).","s":0},{"q":"Un neurone pseudo-unipolaire :","o":["Possède 1 axone et 1 dendrite","Possède > 2 extensions","Présente une extension unique qui se divise en deux bras","N'a pas d'axone"],"r":2,"e":"Le neurone pseudo-unipolaire (ex : ganglion rachidien) a une seule extension qui bifurque.","s":0},{"q":"Les lysosomes contiennent :","o":["Des enzymes oxydatives","Des enzymes hydrolytiques (digestion intracellulaire)","De l'ADN","Des ribosomes"],"r":1,"e":"Lysosomes = vésicules digestives à pH acide, riches en hydrolases.","s":0},{"q":"La centrale énergétique de la cellule (ATP) est :","o":["Le RE","Le Golgi","La mitochondrie","Le noyau"],"r":2,"e":"Mitochondrie : siège de la phosphorylation oxydative et production d'ATP.","s":0},{"q":"Les ribosomes assurent :","o":["La synthèse des lipides","La synthèse protéique","Le stockage du calcium","La détoxification"],"r":1,"e":"Les ribosomes traduisent l'ARNm en protéines (libres ou liés au RER).","s":0},{"q":"Quelle protéine du cytosquelette est la plus fine ?","o":["Microtubules","Filaments intermédiaires","Microfilaments (actine)","Centriole"],"r":2,"e":"Microfilaments d'actine (≈ 7 nm) < filaments intermédiaires (≈ 10 nm) < microtubules (≈ 25 nm).","s":0},{"q":"L'épithélium pseudostratifié cilié se trouve principalement :","o":["Dans l'intestin","Dans la trachée et bronches","Dans la peau","Dans la vessie"],"r":1,"e":"Voies aériennes : épithélium pseudostratifié cilié à cellules caliciformes.","s":0},{"q":"Parmi les molécules de la vie, les nucléotides assurent :","o":["L'information génétique et l'énergie sous forme d'ATP","La structure et les enzymes","Les membranes et la réserve","L'énergie et la structure"],"r":0,"e":"Les glucides apportent énergie et structure, les protéines structure, enzymes et transport, les lipides membranes, réserve et signalisation.","s":0},{"q":"Le solvant universel de la cellule est :","o":["L'eau","Le cytoplasme","Le plasma","Le liquide interstitiel"],"r":0,"e":"La vie de la cellule résulte des interactions entre ses molécules selon un plan harmonieux.","s":0},{"q":"La compartimentation permet :","o":["L'organisation en organites et la séparation de réactions chimiques incompatibles","La seule organisation en organites","Le seul transport","La seule protection"],"r":0,"e":"Les procaryotes, sans noyau et sans compartimentation, en sont dépourvus.","s":0},{"q":"La pinocytose concerne :","o":["Des particules solides comme les bactéries","Des particules dissoutes dans un liquide, avec des vésicules plus petites","Des molécules liées à des récepteurs","Des molécules sortantes"],"r":1,"e":"La phagocytose concerne les particules solides et l'endocytose médiée par récepteurs une substance spécifique reconnue.","s":0},{"q":"L'ARN ribosomique a pour fonction :","o":["De constituer les ribosomes","De transporter l'information du noyau au ribosome","D'apporter les acides aminés","De répliquer l'ADN"],"r":0,"e":"L'ARNm transporte l'information et l'ARNt apporte les acides aminés.","s":0},{"q":"Le caryotype humain comporte :","o":["23 chromosomes","46 chromosomes, soit 23 paires","44 chromosomes","48 chromosomes"],"r":1,"e":"La mitose produit deux cellules filles diploïdes identiques, la méiose quatre cellules haploïdes.","s":0},{"q":"La phase G2 du cycle cellulaire correspond :","o":["À l'intervalle entre la fin de la duplication et le début de la division","À l'intervalle entre division et synthèse d'ADN","À la réplication de l'ADN","À la division elle-même"],"r":0,"e":"G1 sépare division et synthèse, S correspond à la réplication ; l'ensemble forme l'interphase.","s":0},{"q":"La méiose I assure :","o":["La séparation des chromosomes homologues","La séparation des chromatides sœurs","La réplication de l'ADN","La formation de deux cellules diploïdes"],"r":0,"e":"La méiose II sépare, elle, les chromatides sœurs.","s":0},{"q":"Les stéréocils se définissent comme :","o":["Des microvillosités longues et immobiles, présentes dans l'épididyme et l'oreille interne","Des cils mobiles","Des microvillosités courtes","Des jonctions"],"r":0,"e":"Les microvillosités augmentent la surface d'absorption et les cils assurent un mouvement de surface.","s":0},{"q":"L'indice mitotique élevé du tissu épithélial explique :","o":["Son renouvellement constant et sa susceptibilité aux carcinomes","Sa vascularisation","Son absence de membrane basale","Sa rigidité"],"r":0,"e":"Le tissu épithélial se caractérise aussi par l'absence de substance interstitielle et la présence d'une membrane basale.","s":0},{"q":"Les joints imperméables, ou jonctions étanches :","o":["Empêchent le passage d'ions et de molécules entre cellules, formant des barrières de perméabilité","Permettent le passage ionique","Relient fortement les cellules","Assurent la contraction"],"r":0,"e":"L'épithélium intestinal en est l'exemple cité.","s":0},{"q":"L'épithélium simple pavimenteux permet :","o":["Une diffusion bidirectionnelle de gaz et de fluides, formant barrière entre tissus et sang","La sécrétion hormonale","L'absorption active","La distension"],"r":0,"e":"Le simple cubique assure protection, sécrétion et absorption dans les ovaires, le rein, la thyroïde et la rétine.","s":0},{"q":"L'épithélium simple cylindrique se rencontre notamment :","o":["Dans la trompe de Fallope","Dans les bronches","Dans l'épiderme","Dans la vessie"],"r":0,"e":"Ses cellules sont densément compactées, à noyau ovoïde central ou basal, avec microvillosités et parfois cils.","s":0},{"q":"L'épithélium stratifié pavimenteux non kératinisé se rencontre :","o":["Dans les zones humides : cavité buccale, pharynx, œsophage, vagin et cornée","Dans l'épiderme","Dans les bronches","Dans le tractus urinaire"],"r":0,"e":"La forme kératinisée, avec cellules mortes sans noyau remplies de kératine, occupe l'épiderme, le tympan et des parties de la bouche.","s":0},{"q":"L'urothélium s'adapte à la distension en passant de :","o":["5 à 7 couches à vide, à 2 ou 3 couches en distension","2 couches à 7 couches","10 à 5 couches","Un nombre constant de couches"],"r":0,"e":"Il forme une barrière contre l'urine dans le tractus urinaire.","s":0},{"q":"Les glandes endocrines se distinguent des exocrines par :","o":["Une sécrétion directe dans le sang, sans canal","Une sécrétion vers une surface via un canal","L'absence de sécrétion","Une sécrétion apicale"],"r":0,"e":"Les deux constituent les épithéliums glandulaires.","s":0},{"q":"Parmi les cellules du tissu conjonctif figurent :","o":["Fibroblastes, macrophages, mastocytes, plasmocytes, adipocytes et leucocytes","Chondrocytes et ostéocytes seuls","Kératinocytes","Neurones"],"r":0,"e":"Fibres — collagènes, réticulaires et élastiques — et substance interstitielle en constituent les autres composants.","s":0},{"q":"Le tissu conjonctif dense irrégulier se caractérise par :","o":["Des faisceaux de collagène à orientation aléatoire, comme dans le derme","Un motif défini, comme dans les tendons","Un réseau réticulaire","Une substance interstitielle abondante"],"r":0,"e":"Le dense régulier, à motif défini, forme tendons et ligaments.","s":0},{"q":"Le tissu réticulaire se rencontre :","o":["Dans les organes lymphoïdes et hématopoïétiques","Dans le derme","Dans les tendons","Dans le cartilage"],"r":0,"e":"Il associe un réseau de fibres réticulaires, des cellules réticulaires et des cellules phagocytaires.","s":0},{"q":"Le tissu muqueux se caractérise par :","o":["Une substance interstitielle abondante riche en acide hyaluronique, d'aspect gélatineux","Des fibres élastiques parallèles","Un réseau réticulaire","Des adipocytes"],"r":0,"e":"Il contient des fibroblastes ; le tissu élastique, jaunâtre, revient à sa longueur normale après étirement.","s":0},{"q":"Quelle est la fonction principale de la peau qui n'est PAS dans cette liste ?","o":["Protection","Sensation","Production de globules rouges","Régulation de la température"],"r":2,"e":"La peau ne produit pas de globules rouges (rôle de la moelle osseuse).","s":1},{"q":"Quel récepteur détecte la chaleur ?","o":["Corpuscule de Krause","Corpuscule de Ruffini","Corpuscule de Meissner","Disque de Merkel"],"r":1,"e":"Krause = froid ; Ruffini = chaleur.","s":1},{"q":"Les terminaisons nerveuses libres détectent :","o":["La pression","Le toucher fin","La douleur","Le froid"],"r":2,"e":"Terminaisons nerveuses libres = nocicepteurs = douleur.","s":1},{"q":"L'épiderme est :","o":["Très vascularisé","Avasculaire","Riche en adipocytes","Du tissu conjonctif"],"r":1,"e":"L'épiderme est avasculaire ; c'est un épithélium stratifié pavimenteux kératinisé.","s":1},{"q":"La peau épaisse possède combien de couches dans l'épiderme ?","o":["3","4","5","6"],"r":2,"e":"Peau épaisse = 5 couches (paume des mains et plante des pieds) ; peau fine = 4 couches.","s":1},{"q":"Quelle cellule produit la mélanine ?","o":["Kératinocyte","Mélanocyte","Cellule de Langerhans","Cellule de Merkel"],"r":1,"e":"Les mélanocytes produisent la mélanine et la transfèrent aux kératinocytes via les mélanosomes.","s":1},{"q":"Les cellules de Langerhans participent :","o":["À la thermorégulation","À la réponse immunitaire","À la sensation tactile","À la pigmentation"],"r":1,"e":"Les cellules de Langerhans (cellules dendritiques épidermiques) participent à la réponse immunitaire.","s":1},{"q":"Dans quelle couche de l'épiderme se déroule la mitose la plus intense ?","o":["Cornée","Lucide","Épineuse","Basale"],"r":3,"e":"La couche basale (germinative) est en contact avec le derme et a un taux de mitose élevé.","s":1},{"q":"La couche lucide est présente :","o":["Sur tout le corps","Uniquement sur la paume et la plante","Uniquement sur le visage","Uniquement sur le cuir chevelu"],"r":1,"e":"La couche lucide se trouve uniquement dans la peau épaisse : paume des mains et plante des pieds.","s":1},{"q":"Les desmosomes caractérisent quelle couche de l'épiderme ?","o":["Basale","Épineuse","Granuleuse","Cornée"],"r":1,"e":"La couche épineuse tire son nom des protubérances créées par les desmosomes entre les cellules.","s":1},{"q":"La couche papillaire du derme est composée principalement de :","o":["Tissu conjonctif lâche","Tissu conjonctif dense irrégulier","Tissu adipeux","Tissu épithélial"],"r":0,"e":"La couche papillaire est constituée de tissu conjonctif lâche ; la réticulaire est dense irrégulière.","s":1},{"q":"Les empreintes digitales résultent :","o":["De la kératinisation","Des papilles dermiques","Des glandes sudoripares","De la mélanine"],"r":1,"e":"Les papilles dermiques aux extrémités des doigts forment les crêtes et sillons des empreintes digitales.","s":1},{"q":"L'hypoderme représente environ :","o":["1-5 % du poids corporel","5-10 %","15-30 %","40-50 %"],"r":2,"e":"L'hypoderme représente 15 à 30 % du poids corporel.","s":1},{"q":"Combien de temps dure en moyenne la phase anagène (croissance) d'un cheveu ?","o":["1 semaine à 1 mois","14 à 28 jours","90 jours","2 à 7 ans"],"r":3,"e":"Anagène = 2-7 ans (moyenne 3 ans) ; catagène = 14-28 jours ; télogène = 90 jours.","s":1},{"q":"Quelle est la phase du cycle pilaire pendant laquelle le poil tombe ?","o":["Anagène","Catagène","Télogène","Métagène"],"r":2,"e":"La phase télogène est la phase stationnaire de repos qui se termine par la chute du poil.","s":1},{"q":"Le cortex du cheveu contient :","o":["Uniquement des écailles","Kératine et mélanine","Du sébum","De l'élastine"],"r":1,"e":"Le cortex = masse de kératine + pigments de mélanine ; il représente 90 % du poids du cheveu.","s":1},{"q":"Les glandes sébacées sont absentes :","o":["Du cuir chevelu","Du visage","De la paume des mains et de la plante des pieds","Du tronc"],"r":2,"e":"Les glandes sébacées sont absentes de la paume des mains et de la plante des pieds (où il n'y a pas de poils).","s":1},{"q":"L'acné est aggravée par :","o":["Les œstrogènes","Les androgènes","L'insuline","La thyroxine"],"r":1,"e":"Les androgènes stimulent les glandes sébacées → hypersécrétion + obstruction du follicule = acné.","s":1},{"q":"Le sébum permet notamment :","o":["La thermorégulation","L'imperméabilisation et l'inhibition bactérienne","La production de mélanine","La transpiration"],"r":1,"e":"Sébum = mélange complexe qui imperméabilise, lubrifie et inhibe la croissance bactérienne.","s":1},{"q":"La synthèse de la vitamine D nécessite l'activation finale par :","o":["Le pancréas","Le cerveau","Le foie et les reins","La rate"],"r":2,"e":"Le précurseur activé par UV est ensuite modifié par le foie puis les reins → calciférol.","s":1},{"q":"En cas d'augmentation de température, la peau réagit par :","o":["Vasoconstriction et ↓ sueur","Vasodilatation et ↑ sueur","Vasoconstriction et ↑ sueur","Vasodilatation et ↓ sueur"],"r":1,"e":"↑ T° → vasodilatation cutanée + ↑ sueur → perte de chaleur par évaporation.","s":1},{"q":"Quelle substance est négligeable dans l'absorption cutanée ?","o":["Vitamine A","Vitamine D","Substance soluble dans l'eau","Acétone"],"r":2,"e":"L'absorption des substances hydrosolubles est négligeable ; les liposolubles (A, D, E, K, solvants) traversent la peau.","s":1},{"q":"Une brûlure du 2ᵉ degré se caractérise par :","o":["Une simple rougeur","Des cloques (phlyctènes)","Une couleur noire","Atteinte osseuse"],"r":1,"e":"2ᵉ degré = épiderme + partie du derme → formation de cloques.","s":1},{"q":"Selon la règle des 9 %, la paume de la victime correspond approximativement à :","o":["0,5 % de la surface corporelle","1 %","5 %","9 %"],"r":1,"e":"La paume de la victime ≈ 1 % de la surface corporelle, utile pour évaluer les brûlures localisées.","s":1},{"q":"Une coloration jaune de la peau (jaunisse) est due à :","o":["Une carence en oxygène","Une accumulation de bilirubine","Une réaction allergique","Un excès de mélanine"],"r":1,"e":"Jaunisse = bilirubine dans la peau, souvent liée à un problème hépatique. Cyanose = manque d'O₂ ; érythème = allergie.","s":1},{"q":"La couche cornée de l'épiderme est composée de :","o":["Cellules vivantes pigmentées","Cellules mortes kératinisées","Adipocytes","Fibroblastes"],"r":1,"e":"Stratum corneum : cellules mortes anucléées remplies de kératine, formant la barrière externe.","s":1},{"q":"Les récepteurs sensoriels du tact discriminatif (fines pressions) sont :","o":["Corpuscules de Pacini","Corpuscules de Meissner","Corpuscules de Ruffini","Disques de Merkel"],"r":1,"e":"Meissner = tact léger / discrimination ; Pacini = vibrations / pression profonde ; Ruffini = étirement ; Merkel = pression soutenue.","s":1},{"q":"Une brûlure du 3ᵉ degré atteint :","o":["Uniquement l'épiderme","L'épiderme et une partie du derme","Toute l'épaisseur (épiderme + derme + parfois hypoderme)","Uniquement l'hypoderme"],"r":2,"e":"3ᵉ degré : destruction totale épiderme + derme ± hypoderme, indolore (destruction des terminaisons nerveuses).","s":1},{"q":"Lors d'une exposition au froid, la peau :","o":["Vasodilate et augmente la sudation","Vasoconstricte (frissons, piloérection) pour conserver la chaleur","Reste inchangée","Augmente la sécrétion sébacée"],"r":1,"e":"Thermorégulation au froid : vasoconstriction cutanée, frissons, piloérection (chair de poule) pour limiter les pertes.","s":1},{"q":"L'ongle pousse à partir :","o":["De la cuticule","De la matrice unguéale (sous la lunule)","Du bord libre","De l'éponychium"],"r":1,"e":"La matrice (sous la lunule blanche) est la zone germinative produisant la kératine de l'ongle.","s":1},{"q":"La peau constitue une réserve sanguine contenant :","o":["8 à 10 % du sang total","20 % du sang","2 % du sang","30 % du sang"],"r":0,"e":"C'est l'une des six fonctions du système tégumentaire, avec protection, sensation, thermorégulation, vitamine D et excrétion.","s":1},{"q":"La fonction d'excrétion de la peau porte sur :","o":["La sueur, les sels, le CO₂, l'ammoniac et l'urée","L'urine seule","Le sébum seul","Les hormones"],"r":0,"e":"La production de vitamine D repose, elle, sur l'activation d'un précurseur par les UV en calciférol.","s":1},{"q":"Les corpuscules de Paccini détectent :","o":["La pression et la vibration","Le toucher léger","Le froid","La chaleur"],"r":0,"e":"Meissner détecte le toucher léger, Krause le froid, Ruffini la chaleur et les terminaisons libres la douleur.","s":1},{"q":"Un centimètre carré de peau contient en moyenne :","o":["1 m de vaisseaux sanguins, 4 m de nerfs et 200 terminaisons nerveuses","10 cm de vaisseaux","10 m de nerfs","20 terminaisons nerveuses"],"r":0,"e":"S'y ajoutent 20 à 200 poils, 15 glandes sébacées et 150 glandes sudoripares.","s":1},{"q":"Un centimètre carré de peau compte en moyenne :","o":["2 récepteurs de chaleur et 13 récepteurs de froid","13 récepteurs de chaleur et 2 de froid","10 de chaque","Aucun thermorécepteur"],"r":0,"e":"Il compte aussi 10 à 25 récepteurs de pression.","s":1},{"q":"Le derme est constitué de tissu conjonctif contenant :","o":["Collagène, élastine et glycosaminoglycanes","Kératine","Mélanine","Sébum"],"r":0,"e":"Très vascularisé, il assure soutien, nutrition, fermeté et élasticité ; l'épiderme est au contraire avasculaire.","s":1},{"q":"La mélanine est transférée aux kératinocytes par :","o":["Les mélanosomes","Les desmosomes","Les lysosomes","Les vésicules de Langerhans"],"r":0,"e":"Les mélanocytes la produisent comme pigment et protection contre les UV.","s":1},{"q":"Les kératinocytes représentent environ :","o":["50 % des cellules épidermiques","90 % des cellules épidermiques","10 %","30 %"],"r":1,"e":"Ils produisent la kératine, qui imperméabilise et protège contre la déshydratation.","s":1},{"q":"La couche épineuse de l'épiderme comprend :","o":["8 à 10 couches de kératinocytes reliés par des desmosomes","3 à 5 couches","15 à 30 couches","Une seule couche"],"r":0,"e":"Elle contient les cellules de Langerhans et voit débuter la synthèse de kératine et la sécrétion d'un glycolipide hydrofuge.","s":1},{"q":"La couche granuleuse comprend :","o":["3 à 5 couches de kératinocytes aplatis dont les noyaux et organites se désintègrent","8 à 10 couches","15 à 30 couches","Une seule couche"],"r":0,"e":"Ces cellules sont en cours de mort, remplies de kératine.","s":1},{"q":"La couche cornée comprend :","o":["15 à 30 couches de cellules mortes et sèches, fortement kératinisées","3 à 5 couches","8 à 10 couches","Une seule couche"],"r":0,"e":"Elle empêche la pénétration des micro-organismes et la déshydratation.","s":1},{"q":"La couche lucide contient :","o":["Une protéine claire riche en lipides, formant une barrière contre l'eau","De la mélanine","Des cellules de Langerhans","Des mélanocytes"],"r":0,"e":"Elle n'existe que dans la peau épaisse de la paume et de la plante.","s":1},{"q":"La couche réticulaire du derme est constituée :","o":["De tissu conjonctif dense irrégulier riche en collagène et élastine, pauvre en cellules","De tissu conjonctif lâche","De tissu adipeux","D'épithélium"],"r":0,"e":"Elle contient vaisseaux, glandes sébacées et sudoripares, récepteurs de pression et cellules phagocytaires.","s":1},{"q":"L'hypoderme représente :","o":["15 à 30 % du poids corporel","5 % du poids","50 % du poids","2 % du poids"],"r":0,"e":"Son épaisseur varie selon la localisation, le sexe et l'âge.","s":1},{"q":"La cuticule du cheveu comprend :","o":["8 à 10 couches d'écailles dures et transparentes, qui réfléchissent la lumière","Un canal vide","De la mélanine","De la kératine spongieuse"],"r":0,"e":"Le cortex représente 90 % du poids du cheveu et la moelle n'existe pas dans tous les poils.","s":1},{"q":"Les liaisons du cortex du cheveu comprennent :","o":["Des liaisons saline, hydrogène et le pont disulfure, base de la permanente","Des desmosomes","Des jonctions gap","Des liaisons peptidiques seules"],"r":0,"e":"Le cortex associe kératine et mélanine, responsable de la couleur.","s":1},{"q":"La phase catagène du cycle pilaire dure :","o":["14 à 28 jours","2 à 7 ans","Environ 90 jours","1 an"],"r":0,"e":"C'est la phase d'involution catabolique, où le follicule se désintègre et remonte.","s":1},{"q":"À tout instant, la proportion de follicules en phase télogène est d'environ :","o":["1 %","13 %","50 %","90 %"],"r":1,"e":"Environ 1 % sont en catagène, et l'on perd environ 100 cheveux par jour sur 100 000 follicules.","s":1},{"q":"Le sébum est composé de :","o":["Triglycérides, cholestérol, protéines et sels minéraux","Kératine et mélanine","Eau et électrolytes","Collagène"],"r":0,"e":"Les glandes sébacées sont plus nombreuses sur le visage, le cuir chevelu et la partie supérieure du tronc.","s":1},{"q":"L'ongle est formé :","o":["De cellules épidermiques kératinisées mortes constituant la plaque cornée","De derme","De cartilage","De collagène"],"r":0,"e":"Les cellules basales se multiplient en permanence, accumulent la kératine en montant, meurent et se compactent.","s":1},{"q":"Quelle proportion de lipides compose la membrane plasmique selon le modèle de la mosaïque fluide ?","o":["10-20 %","25-35 %","45-50 %","70-80 %"],"r":2,"e":"La membrane plasmique = 45-50 % lipides, 45-50 % protéines, 4-8 % glucides.","s":2},{"q":"Le cholestérol membranaire :","o":["Forme la majeure partie de la membrane","Modifie la fluidité de la membrane","Constitue les pores aqueux","N'est pas présent dans les membranes animales"],"r":1,"e":"Le cholestérol s'insère entre les queues hydrophobes et module la fluidité membranaire.","s":2},{"q":"Les glucides membranaires sont situés :","o":["Au cœur de la bicouche","Sur la face intracellulaire","Sur la face extracellulaire","Dans les organites"],"r":2,"e":"Les glucides sont fixés aux protéines et lipides sur la face extracellulaire (glycoprotéines, glycolipides).","s":2},{"q":"Quelle molécule traverse directement la bicouche lipidique ?","o":["Glucose","Acides aminés","O₂","Na⁺"],"r":2,"e":"O₂ est liposoluble et traverse facilement la bicouche ; glucose et acides aminés nécessitent des transporteurs.","s":2},{"q":"La diffusion est :","o":["Active, contre le gradient","Passive, en faveur du gradient","Nécessite de l'ATP","Spécifique à un transporteur"],"r":1,"e":"La diffusion est un transport passif, en faveur du gradient, sans dépense d'énergie.","s":2},{"q":"L'osmose concerne :","o":["Tous les solutés","Uniquement les ions","L'eau à travers une membrane semi-perméable","Les protéines"],"r":2,"e":"L'osmose = diffusion de l'eau à travers une membrane semi-perméable, du milieu hypotonique vers le milieu hypertonique.","s":2},{"q":"L'eau se déplace par osmose vers :","o":["La solution hypotonique","La solution hypertonique","Aucun déplacement","La solution isotonique"],"r":1,"e":"L'eau va vers la solution la plus concentrée en soluté (hypertonique) pour équilibrer les concentrations.","s":2},{"q":"Lequel n'est PAS une caractéristique du transport médié ?","o":["Spécificité","Compétition","Saturation","Aucune liaison avec une protéine"],"r":3,"e":"Le transport médié repose sur des protéines (canaux, transporteurs, pompes) → spécificité, compétition, saturation.","s":2},{"q":"La diffusion facilitée :","o":["Consomme de l'ATP","Va contre le gradient","Utilise des protéines, sans dépense d'énergie","Concerne uniquement l'eau"],"r":2,"e":"Diffusion facilitée = transport médié en faveur du gradient, sans dépense d'énergie.","s":2},{"q":"La pompe Na⁺/K⁺ déplace :","o":["3 Na⁺ entrent et 2 K⁺ sortent","3 Na⁺ sortent et 2 K⁺ entrent","2 Na⁺ sortent et 3 K⁺ entrent","1 Na⁺ pour 1 K⁺"],"r":1,"e":"La pompe Na⁺/K⁺ expulse 3 Na⁺ et importe 2 K⁺, en consommant de l'ATP.","s":2},{"q":"Le transport actif secondaire utilise :","o":["L'ATP directement","Le gradient de Na⁺ créé par la pompe Na⁺/K⁺","La diffusion de l'eau","Les canaux à porte voltage"],"r":1,"e":"Le transport actif secondaire couple l'entrée de Na⁺ (selon son gradient) à l'entrée du glucose ou d'acides aminés contre le gradient.","s":2},{"q":"Les aquaporines sont :","o":["Des pompes à ATP","Des protéines-canaux pour l'eau","Des récepteurs hormonaux","Des phospholipides"],"r":1,"e":"Les aquaporines permettent à l'eau de traverser la membrane à grande vitesse.","s":2},{"q":"Au repos, la membrane est plus perméable :","o":["Au Na⁺","Au K⁺ et au Cl⁻","Au Ca²⁺","Au glucose"],"r":1,"e":"Au repos il y a beaucoup plus de canaux sans porte pour K⁺ et Cl⁻ que pour Na⁺.","s":2},{"q":"Les canaux à porte voltage s'ouvrent en réponse à :","o":["La liaison d'un ligand","Une variation de tension à travers la membrane","Une déformation mécanique","La chaleur"],"r":1,"e":"Les canaux voltage-dépendants s'ouvrent suite à un changement de potentiel membranaire (clés du PA).","s":2},{"q":"Les canaux à porte de liaison sont activés par :","o":["La tension","Un ligand (récepteur)","Une déformation mécanique","Le hasard"],"r":1,"e":"Les canaux à porte de liaison s'ouvrent lorsqu'un ligand se fixe à son récepteur, typique des synapses chimiques.","s":2},{"q":"Le potentiel membranaire au repos est :","o":["Positif à l'intérieur","Nul","Négatif à l'intérieur (environ -70 mV)","Variable selon l'heure"],"r":2,"e":"Au repos, l'intérieur est négatif par rapport à l'extérieur (env. -70 mV pour un neurone).","s":2},{"q":"L'origine principale du potentiel de repos est :","o":["L'entrée massive de Na⁺","La diffusion du K⁺ vers l'extérieur","La sortie de Cl⁻","L'absence d'ions"],"r":1,"e":"Le K⁺ (très concentré à l'intérieur) sort par les canaux sans porte, laissant l'intérieur négatif.","s":2},{"q":"Le potentiel d'action est régi par le principe :","o":["Du tout ou rien","De la sommation continue","De l'inhibition","De la décroissance"],"r":0,"e":"Le potentiel d'action suit la loi du tout ou rien : soit le seuil est atteint et le PA se déclenche complètement, soit rien.","s":2},{"q":"La phase de dépolarisation du PA est due à :","o":["L'ouverture des canaux K⁺","L'ouverture des canaux Na⁺ voltage-dépendants","La fermeture des canaux Cl⁻","La pompe Na⁺/K⁺"],"r":1,"e":"Le seuil ouvre les canaux Na⁺ voltage-dépendants → entrée massive de Na⁺ → dépolarisation rapide.","s":2},{"q":"La repolarisation est due à :","o":["Entrée de Na⁺","Sortie de K⁺ par les canaux voltage","Fermeture des canaux K⁺","Entrée de Ca²⁺"],"r":1,"e":"Au pic du PA : ouverture des canaux K⁺ voltage + fermeture des canaux Na⁺ → sortie de K⁺ → repolarisation.","s":2},{"q":"L'hyperpolarisation se produit car :","o":["Le K⁺ continue à sortir","Le Na⁺ entre","La pompe inverse son sens","Les canaux Cl⁻ s'ouvrent"],"r":0,"e":"Les canaux K⁺ restent ouverts un bref instant après la repolarisation → le K⁺ continue à sortir → l'intérieur devient plus négatif que le repos.","s":2},{"q":"Pendant la période réfractaire, la cellule :","o":["Peut générer un nouveau PA immédiatement","Ne peut pas générer de nouveau PA","Est dépolarisée en permanence","Est morte"],"r":1,"e":"Pendant la période réfractaire, la cellule ne peut pas être dépolarisée → garantit la propagation unidirectionnelle.","s":2},{"q":"Le rétablissement final du potentiel de repos après un PA est assuré par :","o":["Les canaux à porte de liaison","La pompe Na⁺/K⁺","Les aquaporines","Le cholestérol"],"r":1,"e":"La pompe Na⁺/K⁺ rétablit les gradients ioniques après le PA.","s":2},{"q":"Une injection de K⁺ dans le sang est mortelle parce qu'elle :","o":["Diminue la perméabilité au K⁺","Modifie le gradient de K⁺ → dépolarisation cardiaque","Augmente la pression sanguine","Provoque une fièvre"],"r":1,"e":"Une hyperkaliémie diminue le gradient de K⁺ → l'intérieur devient moins négatif → dépolarisation cardiaque non contrôlée → arrêt cardiaque.","s":2},{"q":"Quel canal s'ouvre en réponse à la pression sur la peau ?","o":["Canal à porte de liaison","Canal à porte voltage","Canal à porte mécanique","Canal de fuite"],"r":2,"e":"Les canaux mécaniques s'ouvrent par déformation physique de la membrane (toucher, pression).","s":2},{"q":"La pompe Na⁺/K⁺ ATPase échange :","o":["3 Na⁺ entrants contre 2 K⁺ sortants","3 Na⁺ sortants contre 2 K⁺ entrants","2 Na⁺ contre 3 K⁺","1 Na⁺ contre 1 K⁺"],"r":1,"e":"Pompe Na/K : sort 3 Na⁺ et fait entrer 2 K⁺ par ATP consommé. Maintient les gradients ioniques.","s":2},{"q":"L'osmose désigne :","o":["Le passage de solutés","Le passage d'eau du milieu hypotonique vers le milieu hypertonique","Le passage d'ions","Le transport actif"],"r":1,"e":"Osmose = diffusion passive de l'eau à travers une membrane semi-perméable, du moins concentré au plus concentré.","s":2},{"q":"Le potentiel de repos d'un neurone est environ :","o":["+30 mV","0 mV","-70 mV","-180 mV"],"r":2,"e":"Vrepos ≈ -70 mV, maintenu par la pompe Na/K et la perméabilité au K⁺.","s":2},{"q":"Lors de la dépolarisation, ce sont les canaux qui s'ouvrent :","o":["Canaux K⁺","Canaux Na⁺ voltage-dépendants","Canaux Cl⁻","Aquaporines"],"r":1,"e":"Dépolarisation rapide due à l'entrée de Na⁺ par les canaux voltage-dépendants → inversion de polarité.","s":2},{"q":"La période réfractaire absolue correspond à :","o":["Une période où le neurone est plus excitable","Une période où aucun nouveau PA n'est possible","Une période de repos","La fin du PA"],"r":1,"e":"Pendant la PRA, les canaux Na⁺ sont inactivés → impossible de générer un nouveau PA.","s":2},{"q":"Parmi les fonctions de la membrane cellulaire figure :","o":["L'orientation des réactions","La synthèse protéique","La réplication de l'ADN","La production d'ATP"],"r":0,"e":"S'y ajoutent l'individualisation et la compartimentation, le transport sélectif et la communication et reconnaissance cellulaire.","s":2},{"q":"La propriété d'asymétrie de la membrane signifie :","o":["Que les deux faces ont une composition différente","Que les composants sont mobiles","Que la perméabilité est différenciée","Qu'il n'y a pas de bords libres"],"r":0,"e":"Fluidité, semi-perméabilité, continuité et résistance à la traction complètent ces propriétés.","s":2},{"q":"La propriété de continuité de la membrane signifie :","o":["Qu'elle ne présente pas de bords libres ou discontinus","Qu'elle est imperméable","Qu'elle est rigide","Qu'elle est symétrique"],"r":0,"e":"La résistance à la traction assure, elle, le maintien de l'individualité cellulaire.","s":2},{"q":"Un phospholipide se compose :","o":["D'un groupe phosphate polaire et de deux chaînes d'acides gras apolaires, reliés par du glycérol","D'un seul acide gras","De trois acides gras","De cholestérol"],"r":0,"e":"C'est le lipide principal de la membrane, qui contient 45 à 50 % de lipides.","s":2},{"q":"Les protéines périphériques se situent :","o":["En surface interne ou externe de la bicouche, sans être incorporées dans la zone hydrophobe","Insérées dans la bicouche","Traversant entièrement la membrane","Dans le cytosol"],"r":0,"e":"Les protéines intégrales sont, elles, insérées dans la bicouche et peuvent la traverser entièrement.","s":2},{"q":"Les glucides membranaires forment :","o":["Des glycoprotéines et des glycolipides, du côté extracellulaire","Des phospholipides","Des canaux","Des pompes"],"r":0,"e":"Ils représentent 4 à 8 % de la composition membranaire.","s":2},{"q":"Les grosses molécules polaires comme le glucose et les acides aminés traversent la membrane :","o":["Via des molécules transporteuses protéiques","Directement à travers la bicouche","Par les canaux ioniques","Par vésicules uniquement"],"r":0,"e":"Les molécules liposolubles comme l'oxygène et les stéroïdes se dissolvent directement dans la bicouche.","s":2},{"q":"La filtration se définit comme :","o":["Le passage d'un liquide en mouvement à travers une cloison poreuse, seules les particules plus petites que les pores passant","Le passage de l'eau vers la solution hypertonique","Le mouvement des solutés selon le gradient","Un transport contre le gradient"],"r":0,"e":"La diffusion et l'osmose sont, elles, des mouvements passifs liés au gradient de concentration.","s":2},{"q":"L'injection par erreur d'une solution hypotonique provoque :","o":["Une entrée d'eau dans les globules rouges, qui éclatent — c'est l'hémolyse","Une sortie d'eau","Aucun effet","Une coagulation"],"r":0,"e":"Il faut toujours utiliser une solution isotonique, comme le NaCl à 0,9 %.","s":2},{"q":"La compétition, dans le transport médié, signifie que :","o":["Des molécules similaires se disputent le même site, la plus concentrée ou la plus affine étant transportée plus vite","Chaque protéine ne lie qu'un type de molécule","La vitesse est limitée par le nombre de protéines","Le transport est bidirectionnel"],"r":0,"e":"La spécificité et la saturation complètent les trois caractéristiques du transport médié.","s":2},{"q":"La saturation du transport médié signifie que :","o":["La vitesse est limitée par le nombre de protéines disponibles","Le gradient s'annule","L'ATP manque","Les molécules se lient entre elles"],"r":0,"e":"C'est ce qui distingue le transport médié de la diffusion simple, non saturable.","s":2},{"q":"Le transport actif secondaire couple :","o":["L'entrée du sodium en faveur de son gradient à l'entrée du glucose ou d'un acide aminé contre le leur","Deux transports actifs primaires","Deux diffusions simples","L'ATP et le calcium"],"r":0,"e":"Il exploite le gradient créé par la pompe Na⁺/K⁺, qui est un transport actif primaire.","s":2},{"q":"Le canal de fuite se caractérise par :","o":["Une ouverture et une fermeture aléatoires, au repos","Une ouverture par un ligand","Une ouverture par le voltage","Une ouverture par déformation physique"],"r":0,"e":"Les canaux mécaniques s'ouvrent, eux, par déformation physique et sous-tendent le sens du toucher.","s":2},{"q":"La membrane au repos est plus perméable au potassium et au chlore grâce :","o":["À un plus grand nombre de canaux sans porte pour ces ions","Aux pompes","Aux canaux voltage-dépendants","Aux aquaporines"],"r":0,"e":"La membrane est 50 à 100 fois moins perméable au sodium.","s":2},{"q":"Dans la genèse du potentiel de repos, les protéines intracellulaires :","o":["Sont négatives et ne peuvent pas suivre le potassium qui sort","Sont positives","Traversent la membrane","Sont neutres"],"r":0,"e":"Cela rend l'intérieur négatif, ce qui attire en retour les ions potassium jusqu'à l'équilibre.","s":2},{"q":"Au repos, la perméabilité au calcium est :","o":["Faible","Élevée","Identique à celle du potassium","Nulle"],"r":0,"e":"Le chlore a une perméabilité relative, mais il est repoussé par la charge interne négative.","s":2},{"q":"L'injection intraveineuse de potassium provoque :","o":["Une augmentation du potassium extracellulaire, une diminution du gradient, puis une dépolarisation cardiaque incontrôlée et un arrêt cardiaque","Une hyperpolarisation","Une bradycardie isolée","Aucun effet"],"r":0,"e":"C'est le mécanisme utilisé dans la peine de mort et l'euthanasie.","s":2},{"q":"Au pic du potentiel d'action :","o":["Les canaux potassium voltage-dépendants s'ouvrent et les canaux sodium se ferment","Les canaux sodium s'ouvrent","Tous les canaux se ferment","La pompe s'arrête"],"r":0,"e":"La sortie de potassium assure alors la repolarisation.","s":2},{"q":"Le retour au potentiel de repos après un potentiel d'action est assuré par :","o":["La fermeture des canaux potassium et l'action de la pompe Na⁺/K⁺","La seule pompe","La seule fermeture des canaux","L'ouverture des canaux sodium"],"r":0,"e":"C'est la cinquième et dernière étape du potentiel d'action.","s":2},{"q":"La dépolarisation se définit comme :","o":["Le fait que l'intérieur devienne moins négatif, voire positif","Le retour vers une valeur négative","Le fait de devenir plus négatif que le repos","L'absence de variation"],"r":0,"e":"La repolarisation ramène vers la valeur de repos et l'hyperpolarisation la dépasse en négativité.","s":2},{"q":"Le SNC est composé de :","o":["Encéphale + nerfs","Encéphale + moelle épinière","Moelle + ganglions","Nerfs + plexus"],"r":1,"e":"SNC = encéphale + moelle épinière, protégés par les os (crâne et canal rachidien).","s":3},{"q":"Un ganglion est :","o":["Un nerf","Un agglomérat de corps cellulaires hors du SNC","Un plexus","Une glande"],"r":1,"e":"Un ganglion = amas de corps cellulaires neuronaux situé à l'extérieur du SNC.","s":3},{"q":"La division afférente du SNP :","o":["Transmet du SNC aux effecteurs","Transmet des récepteurs au SNC","Innerve uniquement les glandes","Ne contient pas de neurones"],"r":1,"e":"Afférent = sensoriel = récepteurs → SNC ; efférent = moteur = SNC → effecteurs.","s":3},{"q":"Le système nerveux somatique contrôle :","o":["Muscle cardiaque","Muscle lisse","Muscles squelettiques","Glandes"],"r":2,"e":"Somatique = volontaire, muscles squelettiques. Autonome = involontaire (muscle lisse, cœur, glandes).","s":3},{"q":"Quelle division du SNA prépare à l'action ?","o":["Parasympathique","Sympathique","Entérique","Somatique"],"r":1,"e":"Le sympathique est responsable du 'fight or flight' : accélération cardiaque, dilatation pupilles, etc.","s":3},{"q":"Le système nerveux entérique se trouve :","o":["Dans la moelle épinière","Dans le tronc cérébral","Dans la paroi du tube digestif","Dans les glandes endocrines"],"r":2,"e":"Le système entérique est constitué de plexus dans la paroi des organes digestifs.","s":3},{"q":"La signalisation autonome implique généralement :","o":["Une seule synapse","Deux synapses (pré + postganglionnaire)","Aucune synapse","Trois synapses"],"r":1,"e":"Neurone préganglionnaire (SNC) → ganglion → neurone postganglionnaire → effecteur.","s":3},{"q":"Les synapses électriques utilisent :","o":["Des neurotransmetteurs","Des jonctions gap","Des récepteurs hormonaux","Des canaux à porte de ligand"],"r":1,"e":"Les synapses électriques fonctionnent via les jonctions communicantes (gap) ; rapides, bidirectionnelles.","s":3},{"q":"Dans la synapse chimique, qu'est-ce qui déclenche l'exocytose des neurotransmetteurs ?","o":["Entrée de Na⁺","Entrée de Ca²⁺","Sortie de K⁺","Entrée de Cl⁻"],"r":1,"e":"L'arrivée du PA ouvre les canaux Ca²⁺ voltage → afflux de Ca²⁺ → exocytose des vésicules synaptiques.","s":3},{"q":"Une synapse chimique est :","o":["Bidirectionnelle","Unidirectionnelle","Sans modulation","Plus rapide qu'une synapse électrique"],"r":1,"e":"La synapse chimique est unidirectionnelle (pré → post) ; plus lente que l'électrique mais hautement modulable.","s":3},{"q":"L'unité fonctionnelle de base du système nerveux est :","o":["Le neurone","La synapse","L'arc réflexe","Le ganglion"],"r":2,"e":"Le neurone est l'unité structurelle ; l'arc réflexe est l'unité fonctionnelle de base.","s":3},{"q":"Combien d'éléments composent un arc réflexe ?","o":["3","4","5","6"],"r":2,"e":"5 éléments : récepteur, neurone afférent, neurone d'association, neurone efférent, organe effecteur.","s":3},{"q":"Le réflexe d'extension (myotatique) est particulier car :","o":["Il implique le cerveau","Il n'a pas de neurone d'association","Il est très lent","Il nécessite plusieurs synapses"],"r":1,"e":"Le réflexe d'extension est monosynaptique : neurone sensoriel → directement neurone moteur alpha.","s":3},{"q":"Le réflexe des organes tendineux de Golgi :","o":["Contracte le muscle","Relâche le muscle pour éviter une tension excessive","Augmente la tension","N'utilise pas de neurones d'association"],"r":1,"e":"Le réflexe de Golgi utilise un interneurone inhibiteur pour relâcher le muscle et protéger le tendon.","s":3},{"q":"Le réflexe de retrait utilise :","o":["Un interneurone inhibiteur","Un interneurone excitateur","Aucun interneurone","Une synapse électrique uniquement"],"r":1,"e":"Le réflexe de retrait utilise des interneurones excitateurs sur les fléchisseurs pour éloigner le membre du stimulus douloureux.","s":3},{"q":"Combien de neurones olfactifs possède l'épithélium olfactif ?","o":["10 000","100 000","1 million","10 millions"],"r":3,"e":"Environ 10 millions de neurones olfactifs dans l'épithélium olfactif.","s":3},{"q":"Les axones olfactifs traversent :","o":["Le foramen magnum","La lame criblée","Le chiasma optique","La selle turcique"],"r":1,"e":"Les axones olfactifs traversent la lame criblée pour rejoindre les bulbes olfactifs.","s":3},{"q":"Le goût salé est dû :","o":["À l'activation d'un récepteur couplé à protéine G","À la diffusion de Na⁺ par les canaux ioniques","Aux ions H⁺","À la liaison à un récepteur muscarinique"],"r":1,"e":"Le salé résulte de la diffusion des ions Na⁺ à travers les canaux Na⁺ dans les cellules gustatives.","s":3},{"q":"Les saveurs sucré et amer sont médiées par :","o":["Des canaux ioniques","Des récepteurs couplés à la protéine G","Des canaux à porte mécanique","Des aquaporines"],"r":1,"e":"Sucré et amer activent des récepteurs couplés à la protéine G.","s":3},{"q":"Combien de papilles gustatives compte-t-on ?","o":["1 000","5 000","10 000","100 000"],"r":2,"e":"Environ 10 000 papilles gustatives, chacune contenant ~ 50 cellules gustatives.","s":3},{"q":"Le chiasma optique est situé :","o":["Dans la rétine","Devant l'hypophyse","Dans le cortex occipital","Dans le tronc cérébral"],"r":1,"e":"Le chiasma optique est situé juste devant l'hypophyse ; les fibres nasales s'y croisent.","s":3},{"q":"Combien de muscles extrinsèques bougent chaque œil ?","o":["4","5","6","7"],"r":2,"e":"6 muscles extraoculaires permettent le mouvement de chaque globe oculaire.","s":3},{"q":"Les osselets de l'oreille moyenne sont :","o":["Tympan, marteau, étrier","Marteau, enclume, étrier","Cochlée, vestibule, canaux","Pavillon, conduit, tympan"],"r":1,"e":"Marteau (malléus), enclume (incus), étrier (stapes) — trois osselets de l'oreille moyenne.","s":3},{"q":"L'organe de Corti est situé :","o":["Dans l'oreille externe","Dans l'oreille moyenne","Dans la cochlée (oreille interne)","Dans le nerf vestibulaire"],"r":2,"e":"L'organe de Corti, dans la cochlée, contient les cellules ciliées qui transforment les vibrations en PA.","s":3},{"q":"Le labyrinthe cinétique évalue :","o":["La position de la tête vs gravité","Le mouvement de la tête","La pression artérielle","Le pH sanguin"],"r":1,"e":"Cinétique = mouvement de la tête ; statique = position vs gravité et accélération linéaire.","s":3},{"q":"Combien de paires de nerfs crâniens existent ?","o":["8","10","12","31"],"r":2,"e":"12 paires de nerfs crâniens. Les 31 paires sont les nerfs rachidiens.","s":3},{"q":"Le neurotransmetteur principal de la jonction neuromusculaire est :","o":["GABA","Glutamate","Acétylcholine","Dopamine"],"r":2,"e":"À la plaque motrice, l'acétylcholine est libérée par le motoneurone et active les récepteurs nicotiniques.","s":3},{"q":"La barrière hémato-encéphalique est formée par :","o":["La pie-mère","Les astrocytes et les jonctions serrées des capillaires cérébraux","La dure-mère","Les microglies"],"r":1,"e":"BHE : capillaires à jonctions serrées + pieds astrocytaires. Protège le SNC.","s":3},{"q":"Le réflexe myotatique (rotulien) implique :","o":["2 neurones (monosynaptique)","3 neurones","4 neurones","Aucun neurone"],"r":0,"e":"Réflexe myotatique = monosynaptique : 1 afférent (fuseau) + 1 motoneurone α.","s":3},{"q":"Le système parasympathique a pour neurotransmetteur principal :","o":["Noradrénaline","Acétylcholine","Sérotonine","Histamine"],"r":1,"e":"Para : ACh aux ganglions ET aux effecteurs (récepteurs muscariniques). Sympa : ACh ganglion + noradrénaline effecteurs.","s":3},{"q":"L'homéostasie nécessite trois composants :","o":["Récepteur, centre de contrôle et effecteur","Stimulus, réponse et mémoire","Afférence, intégration et conscience","Nerf, muscle et glande"],"r":0,"e":"C'est l'une des cinq fonctions du système nerveux, avec l'information sensorielle, l'intégration, l'activité mentale et le contrôle des muscles et glandes.","s":3},{"q":"Un plexus, au sein du système nerveux périphérique, désigne :","o":["Un vaste réseau d'axones, et parfois de corps cellulaires, à l'extérieur du SNC","Un agglomérat de corps cellulaires","Un nerf crânien","Un récepteur"],"r":0,"e":"Le ganglion est, lui, un agglomérat de corps cellulaires neuronaux à l'extérieur du SNC.","s":3},{"q":"La division efférente du système nerveux périphérique conduit :","o":["Les potentiels d'action du SNC vers les organes effecteurs","Des récepteurs vers le SNC","Entre deux neurones","Dans les deux sens"],"r":0,"e":"La division afférente, ou sensorielle, conduit au contraire des récepteurs vers le SNC.","s":3},{"q":"Le système sympathique provoque :","o":["Une augmentation de la fréquence cardiaque, une dilatation des bronches et des pupilles et une vasoconstriction périphérique","Une salivation et une digestion accrues","Une bradycardie","Une motilité digestive accrue"],"r":0,"e":"Le parasympathique régule le repos et les fonctions végétatives, selon le schéma « rest and digest ».","s":3},{"q":"Le système nerveux entérique assure :","o":["Le contrôle direct de la motilité et des sécrétions digestives, par des plexus dans la paroi du tube digestif","Le contrôle cardiaque","La régulation thermique","La vision"],"r":0,"e":"Il constitue la troisième composante du système nerveux autonome.","s":3},{"q":"La synapse chimique se caractérise, par rapport à l'électrique, par :","o":["Une transmission lente avec environ 1 ms de délai, unidirectionnelle et fortement modulable","Une transmission quasi-instantanée","Une bidirectionnalité fréquente","Une faible sensibilité pharmacologique"],"r":0,"e":"La synapse électrique passe par des jonctions gap, sans neurotransmetteur, et est peu sensible aux médicaments.","s":3},{"q":"Dans la synapse chimique, le calcium joue le rôle :","o":["De second messager, son afflux déclenchant l'exocytose des neurotransmetteurs","De neurotransmetteur","D'enzyme de dégradation","De récepteur"],"r":0,"e":"Ses canaux voltage-dépendants s'ouvrent à l'arrivée du potentiel d'action au terminal présynaptique.","s":3},{"q":"Les synapses électriques du thalamus régulent :","o":["Le sommeil à ondes lentes, leur interruption pouvant provoquer des convulsions","La vision","La motricité fine","La douleur"],"r":0,"e":"C'est un exemple du rôle fonctionnel des synapses électriques chez l'humain.","s":3},{"q":"Le GABA est décrit comme :","o":["Le principal neurotransmetteur inhibiteur du SNC","Le principal excitateur","Le médiateur du sympathique","Le médiateur de la jonction neuromusculaire"],"r":0,"e":"Le glutamate est le principal excitateur et la noradrénaline le médiateur sympathique.","s":3},{"q":"La dopamine intervient notamment dans :","o":["La récompense et la motricité, son déficit étant lié à la maladie de Parkinson","L'humeur et le sommeil","L'inhibition du SNC","La modulation de la douleur"],"r":0,"e":"La sérotonine régule humeur et sommeil, et les endorphines modulent la douleur.","s":3},{"q":"Dans le circuit sensori-moteur, le relais vers le cortex se fait par :","o":["Le thalamus","Le cervelet","Les noyaux gris centraux","Le bulbe"],"r":0,"e":"La voie sensorielle ascendante y fait relais avant d'atteindre le cortex, où naît la perception consciente.","s":3},{"q":"Le neurone moteur supérieur descend :","o":["Du cortex frontal vers la moelle épinière","De la moelle vers le muscle","Du thalamus vers le cortex","Du cervelet vers la moelle"],"r":0,"e":"Le neurone moteur inférieur relie ensuite la moelle à la jonction neuromusculaire.","s":3},{"q":"L'arc réflexe est défini comme :","o":["L'unité fonctionnelle, la plus petite partie capable de recevoir un stimulus et de produire une réponse","L'unité structurelle","Un ensemble de neurones sensoriels","Une voie motrice"],"r":0,"e":"Le neurone en constitue, lui, l'unité structurelle.","s":3},{"q":"Un réflexe crânien se caractérise par :","o":["Une intégration dans le cerveau, comme les mouvements des yeux lors de la lecture","Une intégration médullaire","L'absence de SNC","Un apprentissage"],"r":0,"e":"Les réflexes se classent aussi en somatiques et autonomes, innés et acquis.","s":3},{"q":"Les réflexes courts se caractérisent par :","o":["Le fait de ne pas impliquer le SNC, comme les réflexes entériques","L'implication du SNC","Une intégration corticale","Un apprentissage"],"r":0,"e":"Les réflexes longs impliquent, eux, le système nerveux central.","s":3},{"q":"Dans le réflexe myotatique, la détection de l'étirement est assurée par :","o":["Les fuseaux musculaires","Les organes tendineux de Golgi","Les nocicepteurs","Les corpuscules de Paccini"],"r":0,"e":"Les neurones sensoriels font synapse directement avec les motoneurones alpha, sans interneurone.","s":3},{"q":"Le réflexe des organes tendineux de Golgi fait intervenir :","o":["Des neurones d'association inhibiteurs, qui relâchent le muscle","Une synapse directe excitatrice","Des nocicepteurs","Des fuseaux"],"r":0,"e":"Il évite ainsi une tension excessive sur le tendon.","s":3},{"q":"Le réflexe de retrait fait intervenir :","o":["Des récepteurs douloureux et des interneurones excitateurs, entraînant la contraction des fléchisseurs","Des fuseaux musculaires","Des organes de Golgi","Une synapse monosynaptique"],"r":0,"e":"Il retire le membre d'un stimulus douloureux.","s":3},{"q":"Les dendrites des neurones olfactifs forment :","o":["Des vésicules olfactives portant des cils, ou poils olfactifs","Des synapses directes","Des ganglions","Des plexus"],"r":0,"e":"Les récepteurs siègent dans le creux olfactif, à la partie supérieure de la cavité nasale.","s":3},{"q":"Parmi les fonctions du système nerveux, l'activité mentale recouvre :","o":["La conscience, la pensée, la mémoire et les émotions","La seule mémoire","Le seul contrôle moteur","La seule perception"],"r":0,"e":"Le contrôle des muscles et des glandes porte, lui, sur les muscles squelettiques et les sécrétions.","s":3},{"q":"Une hormone est définie par :","o":["Sa composition chimique","Sa fonction (modification du tissu cible)","Sa taille","Sa couleur"],"r":1,"e":"Les hormones sont définies fonctionnellement : elles modifient l'activité d'un tissu cible, quelle que soit leur structure chimique.","s":4},{"q":"Un excès chronique d'hormone provoque :","o":["Up-regulation des récepteurs","Down-regulation des récepteurs","Aucune modification","Disparition des cellules cibles"],"r":1,"e":"Down-regulation : la cellule diminue le nombre de récepteurs → moins sensible à l'hormone.","s":4},{"q":"Quelle hormone est liposoluble ?","o":["Insuline","Cortisol","ADH","Glucagon"],"r":1,"e":"Le cortisol est un stéroïde dérivé du cholestérol, donc liposoluble. Insuline, ADH, glucagon sont des peptides hydrosolubles.","s":4},{"q":"Les hormones hydrosolubles agissent via :","o":["Des récepteurs intracellulaires","Des récepteurs membranaires et un second messager","Le noyau directement","La membrane nucléaire"],"r":1,"e":"Les hormones hydrosolubles ne traversent pas la membrane → récepteurs de surface + second messager (AMPc, Ca²⁺).","s":4},{"q":"L'effet synergique de deux hormones signifie que :","o":["Leur effet combiné est supérieur à la somme de leurs effets séparés","Une hormone bloque l'autre","Une est nécessaire pour que l'autre agisse","Elles ne s'influencent pas"],"r":0,"e":"Synergie : effet combiné > somme. Antagoniste : effets opposés. Permissif : l'une augmente l'action de l'autre.","s":4},{"q":"Le système porte hypothalamo-hypophysaire relie :","o":["Hypothalamus et neurohypophyse","Hypothalamus et adénohypophyse","Hypothalamus et thyroïde","Hypothalamus et surrénales"],"r":1,"e":"Le système porte transporte les neurohormones de l'hypothalamus directement à l'adénohypophyse (antérieure).","s":4},{"q":"Quelle hormone est stockée dans la neurohypophyse ?","o":["TSH","Prolactine","ADH","ACTH"],"r":2,"e":"L'ADH et l'ocytocine sont produites par l'hypothalamus et stockées dans la neurohypophyse.","s":4},{"q":"L'ADH agit principalement sur :","o":["Les reins (réabsorption d'eau)","La thyroïde","Le foie","Les os"],"r":0,"e":"L'ADH augmente la réabsorption d'eau par les tubules rénaux → concentre l'urine.","s":4},{"q":"L'ocytocine est sécrétée par les noyaux :","o":["Supra-optiques","Paraventriculaires","Géniculés","Du raphé"],"r":1,"e":"Ocytocine : noyaux paraventriculaires ; ADH : noyaux supra-optiques.","s":4},{"q":"L'hormone tropique qui stimule la thyroïde est :","o":["TRH","TSH","T3","T4"],"r":1,"e":"TRH (hypothalamus) → TSH (hypophyse) → T3/T4 (thyroïde).","s":4},{"q":"T3 et T4 contiennent un élément clé :","o":["Le fer","L'iode","Le calcium","Le zinc"],"r":1,"e":"Les hormones thyroïdiennes sont synthétisées par fixation d'iode sur la tyrosine.","s":4},{"q":"La calcitonine :","o":["Augmente le calcium sanguin","Diminue le calcium sanguin","N'a pas d'effet sur le calcium","Active la PTH"],"r":1,"e":"La calcitonine inhibe la résorption osseuse et favorise la fixation osseuse du Ca²⁺ → diminue la calcémie.","s":4},{"q":"La parathormone (PTH) :","o":["Diminue le calcium sanguin","Augmente le calcium sanguin","Diminue le potassium sanguin","Augmente l'aldostérone"],"r":1,"e":"La PTH stimule la résorption osseuse, l'absorption intestinale et la réabsorption rénale du Ca²⁺ → augmente la calcémie.","s":4},{"q":"L'aldostérone est sécrétée par :","o":["Médullaire surrénale","Cortex surrénal","Pancréas","Thyroïde"],"r":1,"e":"L'aldostérone (minéralocorticoïde) est produite par le cortex surrénal.","s":4},{"q":"L'aldostérone augmente :","o":["L'excrétion de Na⁺","La réabsorption de Na⁺ et l'excrétion de K⁺","La glycémie","Le calcium sanguin"],"r":1,"e":"Aldostérone : ↑ réabsorption Na⁺, ↑ excrétion K⁺ et H⁺.","s":4},{"q":"Le cortisol est :","o":["Pro-inflammatoire","Anti-inflammatoire","Sans effet sur l'inflammation","Activateur des lymphocytes B"],"r":1,"e":"Le cortisol est anti-inflammatoire : ↓ leucocytes et médiateurs chimiques.","s":4},{"q":"L'adrénaline :","o":["Diminue la fréquence cardiaque","Augmente la glycémie et la FC","Stimule la production de lait","Bloque la lipolyse"],"r":1,"e":"L'adrénaline ↑ FC, ↑ force contractile, ↑ glycémie, prépare à l'effort.","s":4},{"q":"L'insuline est produite par les cellules :","o":["Alpha","Beta","Delta","Acinaires"],"r":1,"e":"Insuline = cellules β ; glucagon = cellules α ; somatostatine = cellules δ.","s":4},{"q":"En cas d'hyperglycémie, le pancréas sécrète :","o":["Glucagon","Insuline","Somatostatine","Adrénaline"],"r":1,"e":"Hyperglycémie → cellules β → insuline → captation du glucose, glycogenèse, lipogenèse → ↓ glycémie.","s":4},{"q":"Le glucagon :","o":["Diminue la glycémie","Augmente la glycémie par glycogénolyse hépatique","Stimule la synthèse de glycogène","Active les cellules β"],"r":1,"e":"Glucagon → ↑ glycémie en stimulant la glycogénolyse et la néoglucogenèse hépatiques.","s":4},{"q":"L'inhibine :","o":["Stimule la FSH","Inhibe la sécrétion de FSH","Stimule la LH","Inhibe la testostérone"],"r":1,"e":"L'inhibine, sécrétée par les gonades, inhibe la sécrétion de FSH par l'hypophyse (rétrocontrôle).","s":4},{"q":"La testostérone est régulée par :","o":["TSH","ACTH","FSH et LH","TRH"],"r":2,"e":"FSH et LH (hypophyse) régulent la production de testostérone par les testicules.","s":4},{"q":"La prolactine est sécrétée par :","o":["L'hypothalamus","L'adénohypophyse","La thyroïde","Le pancréas"],"r":1,"e":"La prolactine est sécrétée par l'adénohypophyse → stimule la production de lait.","s":4},{"q":"Les β-endorphines sont impliquées dans :","o":["La régulation de la glycémie","L'analgésie (stress, exercice)","La pression artérielle","La pigmentation"],"r":1,"e":"Les β-endorphines provoquent une analgésie en réponse au stress et à l'exercice.","s":4},{"q":"L'unité sécrétrice de la thyroïde est :","o":["L'îlot de Langerhans","Le follicule","Le néphron","L'alvéole"],"r":1,"e":"Les follicules thyroïdiens (cellules épithéliales + colloïde rempli de thyroglobuline) sont les unités sécrétrices.","s":4},{"q":"La rétro-action négative (feedback négatif) :","o":["Augmente la sécrétion","Réduit la sécrétion quand la concentration cible est atteinte","Ne s'arrête jamais","Provoque une explosion hormonale"],"r":1,"e":"Mécanisme principal de régulation hormonale : l'effet final inhibe la sécrétion de l'hormone.","s":4},{"q":"L'hormone antidiurétique (ADH) est sécrétée par :","o":["L'antéhypophyse","Le pancréas","La posthypophyse (neurohypophyse)","La thyroïde"],"r":2,"e":"ADH et ocytocine sont synthétisées dans l'hypothalamus et libérées par la posthypophyse.","s":4},{"q":"L'insuline est sécrétée par :","o":["Cellules α du pancréas","Cellules β des îlots de Langerhans","Cellules δ","Cellules acineuses"],"r":1,"e":"Cellules β : insuline (hypoglycémiante) ; cellules α : glucagon (hyperglycémiant).","s":4},{"q":"Le cortisol :","o":["Diminue la glycémie","Augmente la glycémie et l'inflammation est diminuée","Stimule l'ovulation","N'a pas d'effet métabolique"],"r":1,"e":"Cortisol (cortex surrénalien) : ↑ glycémie (néoglucogenèse), effet anti-inflammatoire, libéré au stress.","s":4},{"q":"Une hyperthyroïdie provoque typiquement :","o":["Prise de poids, frilosité, bradycardie","Perte de poids, tachycardie, intolérance à la chaleur","Hypothermie","Aménorrhée seule"],"r":1,"e":"↑ T3/T4 → métabolisme accéléré : perte de poids, tachycardie, chaleur, exophtalmie (Basedow).","s":4},{"q":"Le nombre de récepteurs par cellule pour une hormone donnée est de :","o":["2 000 à 100 000","10 à 100","1 million","Environ 500"],"r":0,"e":"Ces récepteurs sont constamment produits et détruits.","s":4},{"q":"Une hormone manquante entraîne :","o":["Une augmentation du nombre de récepteurs, ou up-regulation, rendant la cellule plus sensible","Une down-regulation","Aucun changement","Une destruction des récepteurs"],"r":0,"e":"Un excès d'hormone provoque au contraire une down-regulation.","s":4},{"q":"Parmi les fonctions du système endocrinien, le cours cite :","o":["La régulation ionique du pH, du sodium, du potassium et du calcium","La seule reproduction","La seule croissance","La seule digestion"],"r":0,"e":"S'y ajoutent métabolisme et maturation des tissus, équilibre hydrique, régulation immunitaire, fonctions cardiovasculaires, contrôle des nutriments, reproduction et lactation.","s":4},{"q":"La régulation non hormonale de la sécrétion repose sur :","o":["L'action d'une autre substance, comme le glucose ou des ions, directement sur la glande","Un contrôle neuronal","Une neurohormone","Un axe hormonal"],"r":0,"e":"Les deux autres modes sont la régulation nerveuse et la régulation hormonale.","s":4},{"q":"Les hormones liposolubles agissent :","o":["En traversant la membrane, sur des récepteurs intracellulaires, avec une action génomique","Par des récepteurs membranaires","Par un second messager","Sans récepteur"],"r":0,"e":"Stéroïdes, hormones thyroïdiennes et monoxyde d'azote en font partie.","s":4},{"q":"Parmi les hormones hydrosolubles, le cours cite :","o":["Les amines, les peptides, les protéines et les eicosanoïdes","Les stéroïdes","Les hormones thyroïdiennes","Le monoxyde d'azote"],"r":0,"e":"Elles agissent par récepteurs membranaires et second messager, AMPc ou calcium.","s":4},{"q":"L'effet permissif se définit comme :","o":["Une hormone qui augmente l'action d'une autre, comme T3/T4 avec l'épinéphrine sur la lipolyse","Un effet combiné supérieur à la somme","Des effets opposés","Une absence d'effet"],"r":0,"e":"L'effet synergique donne un effet combiné supérieur à la somme, comme FSH et œstrogènes ; l'antagonisme oppose insuline et glucagon.","s":4},{"q":"La réponse cellulaire à une hormone dépend :","o":["De sa concentration sanguine, du nombre de récepteurs et de l'influence d'autres hormones","De la seule concentration","Du seul nombre de récepteurs","De la seule durée d'exposition"],"r":0,"e":"Ces trois facteurs expliquent la variabilité des réponses hormonales.","s":4},{"q":"Parmi les rôles de l'hypothalamus, le cours cite :","o":["Le contrôle du système nerveux autonome, de la température, du sommeil et de l'éveil, de la faim et de la soif","La seule régulation hypophysaire","La seule thermorégulation","La seule fonction émotionnelle"],"r":0,"e":"Il est le lien majeur entre système nerveux et système endocrinien.","s":4},{"q":"Les lipotropines ont pour action :","o":["La dégradation des graisses et la libération d'acides gras","La croissance osseuse","La stimulation thyroïdienne","Le dépôt de mélanine"],"r":0,"e":"La MSH assure le dépôt de mélanine et les β-endorphines l'analgésie lors du stress et de l'exercice.","s":4},{"q":"La somatotropine agit sur :","o":["La croissance osseuse, la synthèse protéique et la masse musculaire","La thyroïde","Le cortex surrénal","Les gonades"],"r":0,"e":"TSH, ACTH, FSH et LH sont, elles, des hormones tropiques agissant sur d'autres glandes endocrines.","s":4},{"q":"La demi-vie de l'ocytocine est d'environ :","o":["7 minutes","20 minutes","1 heure","1 minute"],"r":0,"e":"Celle de l'ADH est d'environ 20 minutes ; l'ocytocine est activée par la stimulation des mamelons et la distension utérine.","s":4},{"q":"L'ADH est régulée par :","o":["Les osmorécepteurs hypothalamiques","Les barorécepteurs carotidiens","La TSH","Le glucose sanguin"],"r":0,"e":"Elle augmente la réabsorption rénale d'eau et provoque une vasoconstriction à forte dose.","s":4},{"q":"La thyroïde est structurée en :","o":["Follicules faits de cellules épithéliales sécrétrices, remplis de colloïde contenant la thyroglobuline","Îlots","Acini","Cordons"],"r":0,"e":"Le follicule en est l'unité sécrétrice.","s":4},{"q":"Dans la synthèse des hormones thyroïdiennes :","o":["Deux T2 donnent la T4, et T1 plus T2 donnent la T3","Deux T1 donnent la T4","T3 et T4 sont identiques","T4 est plus active que T3"],"r":0,"e":"On sécrète plus de T4 que de T3, mais la T3 est plus active.","s":4},{"q":"Les hormones thyroïdiennes circulent :","o":["Liées aux TBG, synthétisées par le foie, pour plus de 99 % d'entre elles","Libres à 99 %","Liées à l'albumine seule","Dans les hématies"],"r":0,"e":"Seule la fraction libre est biologiquement active.","s":4},{"q":"L'axe hypothalamo-hypophyso-thyroïdien suit la séquence :","o":["TRH, puis TSH, puis T3 et T4, avec rétrocontrôle négatif","TSH, puis TRH, puis T3/T4","T3/T4, puis TSH","ACTH, puis TSH"],"r":0,"e":"Ce rétrocontrôle explique qu'une TSH élevée traduise une hypothyroïdie périphérique.","s":4},{"q":"La parathormone augmente le calcium sanguin par :","o":["Trois mécanismes : résorption osseuse, absorption intestinale et réabsorption rénale du calcium","La seule résorption osseuse","La seule absorption intestinale","La seule action rénale"],"r":0,"e":"Elle forme avec la calcitonine un couple antagoniste de régulation du calcium.","s":4},{"q":"L'épinéphrine provoque :","o":["Une vasoconstriction de la peau, des reins et des viscères, et une vasodilatation des muscles squelettiques","Une vasodilatation généralisée","Une vasoconstriction généralisée","Une bradycardie"],"r":0,"e":"Elle augmente aussi la glycémie, la fréquence et la force de contraction cardiaques, préparant à l'effort.","s":4},{"q":"Les hormones sont définies :","o":["Par leur action, et non par leur composition chimique, qui est variée","Par leur seule structure protéique","Par leur origine hypophysaire","Par leur solubilité"],"r":0,"e":"Ce sont des messagers chimiques modifiant le fonctionnement des tissus cibles.","s":4},{"q":"Lequel n'est PAS une fonction du cœur ?","o":["Générer la pression artérielle","Filtrer le sang","Assurer un flux unidirectionnel","Réguler l'apport sanguin"],"r":1,"e":"Le cœur ne filtre pas le sang (rôle des reins). Il génère la pression, dirige et assure le flux unidirectionnel.","s":5},{"q":"Le ventricule droit pompe le sang vers :","o":["L'aorte","L'artère pulmonaire","La veine cave","L'oreillette gauche"],"r":1,"e":"Ventricule droit → artère pulmonaire → poumons (circulation pulmonaire).","s":5},{"q":"Quelle valve sépare l'oreillette gauche du ventricule gauche ?","o":["Tricuspide","Mitrale","Aortique","Pulmonaire"],"r":1,"e":"Mitrale (ou bicuspide) à gauche ; tricuspide à droite.","s":5},{"q":"Le pacemaker physiologique du cœur est :","o":["Le nœud AV","Le nœud SA","Le faisceau de His","Les fibres de Purkinje"],"r":1,"e":"Le nœud sinusal (SA) est le pacemaker dominant (~ 70-80/min).","s":5},{"q":"Le plateau du PA des myocytes ventriculaires est dû à :","o":["L'entrée de Na⁺","L'entrée de Ca²⁺","La sortie de K⁺","L'entrée de Cl⁻"],"r":1,"e":"Le plateau est dû à l'entrée prolongée de Ca²⁺. Il rend la période réfractaire longue → pas de tétanisation.","s":5},{"q":"La phase 1 du PA cardiaque ventriculaire (dépolarisation rapide) implique :","o":["Sortie de Na⁺","Entrée de Ca²⁺ uniquement","Entrée de Na⁺","Sortie de K⁺"],"r":2,"e":"La dépolarisation rapide est due à l'ouverture des canaux Na⁺ voltage.","s":5},{"q":"L'onde P de l'ECG correspond à :","o":["La dépolarisation ventriculaire","La dépolarisation auriculaire","La repolarisation auriculaire","La repolarisation ventriculaire"],"r":1,"e":"L'onde P = dépolarisation des oreillettes par le nœud SA.","s":5},{"q":"Le complexe QRS représente :","o":["La dépolarisation auriculaire","La dépolarisation ventriculaire","La repolarisation ventriculaire","Le repos cardiaque"],"r":1,"e":"Le complexe QRS reflète la dépolarisation rapide des ventricules.","s":5},{"q":"L'onde T correspond à :","o":["La dépolarisation ventriculaire","La repolarisation auriculaire","La repolarisation ventriculaire","La systole auriculaire"],"r":2,"e":"L'onde T = repolarisation ventriculaire, précède le relâchement ventriculaire.","s":5},{"q":"Pourquoi la repolarisation auriculaire n'est pas visible sur l'ECG ?","o":["Elle est trop rapide","Elle est masquée par le QRS","Elle n'a pas lieu","Elle est inversée"],"r":1,"e":"La repolarisation auriculaire coïncide avec le complexe QRS et est donc masquée.","s":5},{"q":"L'intervalle P-R représente :","o":["La durée de dépolarisation ventriculaire","Le délai entre dépolarisation auriculaire et ventriculaire","La repolarisation","La systole auriculaire seule"],"r":1,"e":"Intervalle P-R (ou P-Q) = du début de l'onde P au début du QRS = délai entre dépolarisation auriculaire et ventriculaire.","s":5},{"q":"Le segment S-T correspond à :","o":["La phase plateau du PA ventriculaire","La dépolarisation auriculaire","La diastole complète","La période réfractaire absolue"],"r":0,"e":"Le segment S-T correspond au plateau du PA ventriculaire (dépolarisation complète, avant repolarisation).","s":5},{"q":"Durée normale d'un cycle cardiaque chez l'adulte au repos :","o":["0,2 s","0,5 s","0,7-0,8 s","1,5 s"],"r":2,"e":"Cycle normal = 0,7-0,8 s (~ 75/min). Plus long chez l'athlète entraîné, plus court chez le nouveau-né.","s":5},{"q":"La contraction isovolumétrique est caractérisée par :","o":["Toutes les valves ouvertes","Toutes les valves fermées","Seule la valve mitrale ouverte","Éjection du sang"],"r":1,"e":"Pendant la contraction isovolumétrique : toutes les valves fermées, la pression monte sans changement de volume.","s":5},{"q":"Le 1er bruit cardiaque (B1) est dû à :","o":["La fermeture des valves sigmoïdes","La fermeture des valves AV","L'ouverture des valves AV","Le remplissage actif"],"r":1,"e":"B1 = fermeture des valves AV (mitrale + tricuspide), début de la systole ventriculaire.","s":5},{"q":"Le 2ᵉ bruit cardiaque (B2) est dû à :","o":["La fermeture des valves AV","La fermeture des valves sigmoïdes","La systole auriculaire","Le pacemaker"],"r":1,"e":"B2 = fermeture des valves sigmoïdes (aortique + pulmonaire), début de la diastole.","s":5},{"q":"Le volume télédiastolique (fin de diastole) est d'environ :","o":["30 mL","60 mL","120-130 mL","250 mL"],"r":2,"e":"Volume télédiastolique ≈ 120-130 mL ; télésystolique ≈ 50-60 mL.","s":5},{"q":"La valve aortique s'ouvre à une pression d'environ :","o":["25 mmHg","50 mmHg","80 mmHg","120 mmHg"],"r":2,"e":"Valve aortique : ~ 80 mmHg ; valve pulmonaire : ~ 25 mmHg.","s":5},{"q":"La formule du débit cardiaque est :","o":["DC = FC × PAM","DC = FC × VE","DC = VE × RP","DC = PAM / RP"],"r":1,"e":"DC = FC × VE. Au repos : 72 × 70 mL ≈ 5 L/min.","s":5},{"q":"La pression artérielle moyenne (PAM) est définie par :","o":["PAM = FC × VE","PAM = DC × RP","PAM = systolique − diastolique","PAM = systolique + diastolique"],"r":1,"e":"PAM = DC × RP (résistance périphérique).","s":5},{"q":"Quel système nerveux ralentit le cœur ?","o":["Sympathique","Parasympathique","Entérique","Somatique"],"r":1,"e":"Le parasympathique (nerf vague) ralentit la FC ; le sympathique l'accélère.","s":5},{"q":"Lors de la mesure de la PA avec un brassard, le 1er son de Korotkoff indique :","o":["La pression diastolique","La pression systolique","La PAM","La pression veineuse"],"r":1,"e":"1er son = pression systolique ; disparition des sons = pression diastolique.","s":5},{"q":"Le remplissage actif des ventricules est dû :","o":["À la fermeture des valves AV","À la systole auriculaire (contraction)","À la relaxation isovolumétrique","À la contraction ventriculaire"],"r":1,"e":"Le remplissage actif est dû à la contraction des oreillettes (systole auriculaire, onde P), qui complète le remplissage.","s":5},{"q":"Lequel n'est PAS une fonction du sang ?","o":["Transport des gaz","Formation des os","Régulation du pH","Maintien de la T°"],"r":1,"e":"Le sang ne forme pas les os (rôle des ostéoblastes). Il transporte, régule, protège, coagule.","s":5},{"q":"L'épinéphrine (adrénaline) sur le cœur :","o":["Diminue la FC","Augmente la FC et la force contractile","Bloque le nœud SA","N'a pas d'effet"],"r":1,"e":"L'épinéphrine ↑ FC, ↑ force contractile, ↑ DC : préparation à l'effort.","s":5},{"q":"Le débit cardiaque (DC) est :","o":["FC × volume sanguin","FC × volume d'éjection systolique","FC + VES","TA × FC"],"r":1,"e":"DC = FC × VES, environ 5 L/min au repos.","s":5},{"q":"La pression artérielle moyenne (PAM) ≈ :","o":["PA systolique","PA diastolique + 1/3 (PA syst − PA diast)","(PA syst + PA diast) / 2","PA systolique × 2"],"r":1,"e":"PAM ≈ PAdiast + 1/3 (PAsyst − PAdiast), reflet de la pression de perfusion tissulaire.","s":5},{"q":"La grande circulation part de :","o":["Ventricule droit","Ventricule gauche → aorte","Oreillette gauche","Oreillette droite"],"r":1,"e":"Grande circulation : VG → aorte → tissus → VCS/VCI → OD. Petite : VD → AP → poumons → VP → OG.","s":5},{"q":"Sur l'ECG, l'onde P représente :","o":["La dépolarisation ventriculaire","La dépolarisation auriculaire","La repolarisation ventriculaire","La repolarisation auriculaire"],"r":1,"e":"P = dépolarisation auriculaire ; QRS = dépolarisation ventriculaire ; T = repolarisation ventriculaire.","s":5},{"q":"Le baroréflexe :","o":["Augmente la PA en cas d'hypotension","Diminue la PA en cas d'hypotension","Bloque la FC","Stimule la sudation"],"r":0,"e":"Si PA ↓ → baroréflexe ↓ → ↑ sympathique → ↑ FC, vasoconstriction → restaure la PA.","s":5},{"q":"Parmi les quatre propriétés électriques du cœur, la conductivité désigne :","o":["La propagation organisée des potentiels d'action","La génération de ses propres potentiels","La régularité du rythme","La réponse aux stimuli"],"r":0,"e":"Automatisme, rythmicité et excitabilité complètent ces propriétés.","s":5},{"q":"Le rythme spontané du nœud sinusal est d'environ :","o":["30/min","50/min","70 à 80/min","100/min"],"r":2,"e":"Il domine car il est plus rapide que le nœud AV, à environ 50/min, et les ventricules, à environ 30/min.","s":5},{"q":"Le pré-potentiel du nœud sinusal correspond à :","o":["Une dépolarisation spontanée lente par entrée de sodium et de calcium","Une repolarisation","Une hyperpolarisation","Un plateau"],"r":0,"e":"Viennent ensuite la dépolarisation par les canaux calcium, puis la repolarisation par les canaux potassium.","s":5},{"q":"La phase 4 du potentiel d'action ventriculaire correspond à :","o":["La repolarisation finale, par fermeture des canaux calcium et ouverture massive des canaux potassium","Le plateau","La dépolarisation rapide","La repolarisation initiale"],"r":0,"e":"La phase 3, ou plateau, dure environ 0,25 s grâce aux canaux calcium ouverts.","s":5},{"q":"Le plateau calcique du myocyte cardiaque a pour conséquence :","o":["Une période réfractaire longue, empêchant la tétanisation","Une contraction plus rapide","Une conduction accélérée","Une excitabilité accrue"],"r":0,"e":"C'est une spécificité du myocyte cardiaque par rapport au muscle squelettique.","s":5},{"q":"L'onde U de l'ECG correspond à :","o":["La partie finale de la repolarisation ventriculaire","La dépolarisation auriculaire","La dépolarisation ventriculaire","La repolarisation auriculaire"],"r":0,"e":"L'onde T correspond à la repolarisation ventriculaire, avant le relâchement.","s":5},{"q":"L'intervalle Q-T représente :","o":["Du début du QRS à la fin de l'onde T, soit dépolarisation et repolarisation ventriculaires","Du début de P au début du QRS","De la fin de S au début de T","La seule dépolarisation ventriculaire"],"r":0,"e":"Le segment S-T correspond, lui, au plateau du potentiel d'action ventriculaire.","s":5},{"q":"La durée du cycle cardiaque chez le nouveau-né est de :","o":["0,25 à 0,3 s","0,7 à 0,8 s","Plus d'une seconde","1,5 s"],"r":0,"e":"Elle est de 0,7 à 0,8 s chez l'adulte normal et dépasse 1 s chez l'athlète entraîné.","s":5},{"q":"À la fin de la phase d'éjection, le volume ventriculaire tombe à :","o":["50 à 60 mL, le volume télésystolique","120 à 130 mL","20 mL","100 mL"],"r":0,"e":"Le volume télédiastolique, en fin de remplissage, atteint 120 à 130 mL.","s":5},{"q":"À la fin du remplissage passif, les ventricules sont remplis à :","o":["50 % de leur capacité","70 % de leur capacité","90 %","100 %"],"r":1,"e":"La systole auriculaire complète ensuite le remplissage, lors du remplissage actif.","s":5},{"q":"Le troisième bruit cardiaque, parfois audible, correspond à :","o":["Un flux turbulent dans les ventricules lors du remplissage rapide","La fermeture des valves AV","La fermeture des valves sigmoïdes","La contraction auriculaire"],"r":0,"e":"B1 marque la fermeture des valves AV et B2 celle des valves sigmoïdes.","s":5},{"q":"La relaxation isovolumétrique se caractérise par :","o":["Une baisse de pression ventriculaire entraînant la fermeture des valves sigmoïdes, avec le 2ᵉ bruit","L'ouverture des valves AV","L'éjection du sang","La contraction auriculaire"],"r":0,"e":"Elle ouvre la diastole ventriculaire, avant le remplissage passif puis actif.","s":5},{"q":"Lors de la contraction isovolumétrique :","o":["Toutes les valves sont fermées et aucun sang ne sort","Les valves sigmoïdes sont ouvertes","Les valves AV sont ouvertes","Le sang est éjecté"],"r":0,"e":"La pression ventriculaire y monte jusqu'à dépasser celle des artères, ce qui ouvre les valves sigmoïdes.","s":5},{"q":"La circulation pulmonaire suit le trajet :","o":["Ventricule droit, artère pulmonaire, poumons, veines pulmonaires, oreillette gauche","Ventricule gauche, aorte, tissus, veines caves","Oreillette droite, ventricule droit, aorte","Veines pulmonaires, ventricule droit"],"r":0,"e":"L'hématose a lieu au niveau pulmonaire ; la circulation systémique part du ventricule gauche.","s":5},{"q":"Le sang désoxygéné se trouve :","o":["Dans les cavités droites et l'artère pulmonaire","Dans les cavités gauches","Dans les veines pulmonaires","Dans l'aorte"],"r":0,"e":"Le sang oxygéné occupe les cavités gauches, les veines pulmonaires et l'aorte.","s":5},{"q":"Le flux à travers le cœur passe de l'oreillette droite au ventricule droit par :","o":["La valve tricuspide","La valve mitrale","La valve sigmoïde pulmonaire","La valve aortique"],"r":0,"e":"La valve sigmoïde pulmonaire mène ensuite à l'artère pulmonaire.","s":5},{"q":"Parmi les fonctions du cœur, le cours cite :","o":["Réguler l'apport sanguin en adaptant fréquence et force de contraction aux besoins métaboliques","La production d'hormones","La filtration du sang","L'hématopoïèse"],"r":0,"e":"S'y ajoutent la génération de la pression artérielle, la direction de la circulation et le flux unidirectionnel par les valves.","s":5},{"q":"Les fibres de Purkinje assurent :","o":["La dépolarisation rapide des ventricules","Le délai de conduction","La genèse du rythme","La repolarisation"],"r":0,"e":"Le nœud AV assure, lui, le relais avec délai, avant le faisceau de His et ses branches.","s":5},{"q":"L'ECG enregistre :","o":["La somme des potentiels d'action du cœur, chaque tracé électrique précédant un événement mécanique","Les seules contractions","Les bruits cardiaques","Les pressions intracavitaires"],"r":0,"e":"C'est ce décalage qui explique que l'onde P précède la contraction auriculaire.","s":5},{"q":"Le flux unidirectionnel du sang dans le cœur est assuré par :","o":["Les valves cardiaques","Le nœud sinusal","La pression artérielle","Le péricarde"],"r":0,"e":"C'est l'une des quatre fonctions du cœur citées par le cours.","s":5},{"q":"Quelle est la fonction PRINCIPALE du système lymphatique ?","o":["Transport de l'O₂","Équilibre hydrique, absorption des graisses, défense","Production de globules rouges","Régulation hormonale"],"r":1,"e":"Le système lymphatique a 3 fonctions majeures : équilibre hydrique, absorption des graisses, défense immunitaire.","s":6},{"q":"Combien de litres de liquide passent du sang vers l'interstitium chaque jour ?","o":["~ 0,5 L","~ 3 L","~ 10 L","~ 30 L"],"r":1,"e":"~ 3 L/jour sont récupérés par les capillaires lymphatiques et ramenés au sang.","s":6},{"q":"Les chylifères sont :","o":["Des cellules immunitaires","Des vaisseaux lymphatiques de l'intestin grêle absorbant les graisses","Des hormones","Des nodules dans la rate"],"r":1,"e":"Les chylifères sont des vaisseaux lymphatiques spéciaux de la paroi de l'intestin grêle qui absorbent les lipides.","s":6},{"q":"La lymphe est composée de :","o":["Globules rouges et plaquettes","Plasma et globules blancs","Hormones uniquement","Acide hyaluronique"],"r":1,"e":"La lymphe = plasma + globules blancs sortant des capillaires sanguins.","s":6},{"q":"Lequel de ces tissus n'a PAS de capillaires lymphatiques ?","o":["Muscle","Peau","SNC","Foie"],"r":2,"e":"Pas de capillaires lymphatiques dans : SNC, moelle osseuse, cartilage, épiderme, cornée.","s":6},{"q":"Les capillaires lymphatiques :","o":["Ont une membrane basale très épaisse","N'ont pas de membrane basale et sont plus perméables que les capillaires sanguins","Sont identiques aux capillaires sanguins","Sont rares"],"r":1,"e":"Pas de membrane basale + cellules pavimenteuses qui se chevauchent → plus perméables ; fonctionnent comme des valves unidirectionnelles.","s":6},{"q":"Le canal thoracique se déverse dans :","o":["La veine sous-clavière gauche","La veine cave supérieure","L'aorte","La veine sous-clavière droite"],"r":0,"e":"Le canal thoracique draine ¾ du corps vers la veine sous-clavière gauche.","s":6},{"q":"Le canal lymphatique droit draine :","o":["Tout le corps","Le côté droit de la tête, thorax et membre supérieur droit","Tout le côté gauche","Uniquement les jambes"],"r":1,"e":"Le canal lymphatique droit draine le côté droit supérieur du corps vers la veine sous-clavière droite.","s":6},{"q":"La circulation de la lymphe dépend principalement de :","o":["Le cœur","La compression des vaisseaux par les muscles et la respiration","La gravité","Les ondes de pression artérielle"],"r":1,"e":"Pas de pompe propre : compression par muscles squelettiques + muscles lisses des parois + respiration.","s":6},{"q":"Les valves intra-lymphatiques empêchent :","o":["L'entrée de la lymphe","Le reflux de la lymphe","La coagulation","La filtration"],"r":1,"e":"Les valves assurent un flux unidirectionnel et empêchent le reflux.","s":6},{"q":"Combien y a-t-il de ganglions lymphatiques dans le corps environ ?","o":["50","150","450","2000"],"r":2,"e":"Environ 450 ganglions lymphatiques au total.","s":6},{"q":"Quelle région contient le plus grand nombre de ganglions lymphatiques ?","o":["Cervicaux","Axillaires","Abdominaux-pelviens","Inguinaux"],"r":2,"e":"Les ganglions abdominaux-pelviens (~ 230) sont les plus nombreux.","s":6},{"q":"Quelle amygdale est située à la partie postérieure de la langue ?","o":["Palatine","Pharyngée","Linguale","Tubaire"],"r":2,"e":"Amygdale linguale = postérieur de la langue. Palatines = bouche/pharynx. Pharyngée (adénoïde) = nez/pharynx.","s":6},{"q":"La rate :","o":["Produit l'insuline","Détruit les érythrocytes vieillis et filtre le sang","Stocke la bile","Synthétise les anticorps uniquement"],"r":1,"e":"La rate détruit les érythrocytes vieillis, filtre le sang et participe à la réponse immunitaire.","s":6},{"q":"Pendant l'effort, le volume de la rate peut :","o":["Doubler","Diminuer de 40-50 % (réserve de sang)","Rester inchangé","Disparaître"],"r":1,"e":"La rate libère son sang stocké, son volume peut diminuer de 40-50 %, ↑ érythrocytes circulants → ↑ O₂ aux muscles.","s":6},{"q":"Le thymus est le lieu de maturation :","o":["Des lymphocytes B","Des lymphocytes T","Des macrophages","Des plaquettes"],"r":1,"e":"Les lymphocytes T (T pour Thymus) y maturent ; les B mûrissent dans la moelle osseuse.","s":6},{"q":"Avec l'âge, le thymus :","o":["Grossit indéfiniment","Reste de la même taille","Est remplacé par du tissu adipeux","Disparaît dès l'enfance"],"r":2,"e":"Croissance la 1ʳᵉ année puis stable ; vers 40 ans, remplacé en grande partie par du tissu adipeux ; involue vers 60 ans.","s":6},{"q":"L'éléphantiasis est dû à :","o":["Une bactérie","Un nématode obstruant les vaisseaux lymphatiques","Un virus","Un champignon"],"r":1,"e":"Maladie tropicale due à un nématode transmis par les moustiques → obstruction lymphatique → œdème.","s":6},{"q":"Les fibres réticulaires dans les organes lymphatiques :","o":["Servent à la coagulation","Capturent micro-organismes et particules","Stockent la graisse","Conduisent les PA"],"r":1,"e":"Le réseau de fibres réticulaires retient les cellules immunitaires et capture micro-organismes et particules à filtrer.","s":6},{"q":"L'immunité innée se caractérise par :","o":["La mémoire immunitaire","Une réponse non spécifique et rapide","Les anticorps","La maturation thymique"],"r":1,"e":"Innée = non spécifique, immédiate (peau, phagocytes, inflammation). Adaptative = spécifique avec mémoire.","s":6},{"q":"Les lymphocytes B produisent :","o":["Des cytokines","Des anticorps","Du complément","Du sébum"],"r":1,"e":"Les lymphocytes B sont à l'origine des anticorps (immunité humorale).","s":6},{"q":"Les ganglions lymphatiques sont en grande partie situés :","o":["Dans le muscle","Dans le tissu adipeux, à proximité des vaisseaux sanguins","Dans la moelle osseuse","Dans l'os"],"r":1,"e":"Les ganglions sont situés dans le tissu adipeux, à proximité des vaisseaux sanguins.","s":6},{"q":"Le tissu lymphoïde associé aux muqueuses (MALT) comprend notamment :","o":["La rate et le thymus","Les amygdales, les plaques de Peyer et l'appendice","La moelle osseuse rouge uniquement","Le canal thoracique et la citerne du chyle"],"r":1,"e":"Le MALT surveille les portes d'entrée muqueuses : anneau de Waldeyer dans le pharynx, plaques de Peyer dans l'iléon, appendice. Thymus et moelle osseuse sont des organes lymphoïdes primaires (maturation) ; la rate est un organe secondaire, mais non muqueux.","s":6},{"q":"Les plaques de Peyer sont situées :","o":["Dans la paroi de l'iléon","Dans le foie","Dans la rate","Dans le médiastin"],"r":0,"e":"Ce sont des amas de follicules lymphoïdes de la muqueuse de l'intestin grêle, surtout de l'iléon terminal, où la charge bactérienne est la plus forte. Elles échantillonnent le contenu intestinal via les cellules M et déclenchent la réponse immunitaire muqueuse.","s":6},{"q":"Les amygdales palatines sont situées :","o":["Dans le nasopharynx","À l'entrée de l'oropharynx (de part et d'autre du voile du palais)","Dans la moelle osseuse","Dans le médiastin"],"r":1,"e":"Amygdales palatines : oropharynx ; pharyngées : nasopharynx ; linguales : base de la langue.","s":6},{"q":"Le thymus :","o":["Atrophie après la puberté","Grossit avec l'âge","Sécrète des GR","Produit l'urine"],"r":0,"e":"Maximal vers la puberté puis involution avec l'âge. Lieu de maturation des lymphocytes T.","s":6},{"q":"L'immunité innée est :","o":["Spécifique d'un antigène, lente","Non-spécifique, rapide, sans mémoire","Médiée par les lymphocytes B uniquement","Activée seulement chez l'adulte"],"r":1,"e":"Innée : 1ère ligne, rapide, sans mémoire (barrières, phagocytes, complément). Adaptative : spécifique, lente, mémoire.","s":6},{"q":"Les lymphocytes T se différencient dans :","o":["La moelle osseuse","Le thymus","Le foie","La rate"],"r":1,"e":"Lymphocytes T : moelle osseuse → maturation dans le thymus. Lymphocytes B : maturation dans la moelle osseuse.","s":6},{"q":"Un œdème lymphatique survient quand :","o":["Les capillaires sanguins sont trop nombreux","Le drainage lymphatique est obstrué/insuffisant","La PA est trop basse","Les ganglions sont absents à la naissance"],"r":1,"e":"Lymphœdème : accumulation de liquide interstitiel par défaut de drainage (curage ganglionnaire, filariose, congénital).","s":6},{"q":"Les organes lymphatiques comprennent :","o":["Ganglions, rate, thymus, amygdales, moelle osseuse et plaques de Peyer","Ganglions et rate seulement","Le seul thymus","Les seuls vaisseaux"],"r":0,"e":"Vaisseaux lymphatiques et lymphe complètent les composants du système.","s":6},{"q":"La lymphe interstitielle se situe :","o":["Entre les cellules","Dans les vaisseaux lymphatiques","Dans les ganglions","Dans le sang"],"r":0,"e":"La lymphe circulante occupe, elle, l'intérieur des vaisseaux lymphatiques.","s":6},{"q":"La lymphe contient notamment :","o":["Eau, ions, nutriments, gaz, protéines, hormones, enzymes et produits de dégradation","De l'eau seulement","Des érythrocytes","Des plaquettes"],"r":0,"e":"C'est un liquide blanchâtre fait de plasma et de globules blancs sortis des capillaires sanguins.","s":6},{"q":"Les capillaires lymphatiques se distinguent des capillaires sanguins par :","o":["L'absence de membrane basale et des cellules épithéliales pavimenteuses légèrement superposées","Une membrane basale épaisse","Des cellules cubiques","Une paroi musculaire"],"r":0,"e":"Leur épithélium fonctionne comme des valves unidirectionnelles : le liquide entre mais ne sort pas.","s":6},{"q":"La citerne de Pecquet correspond :","o":["À la dilatation à l'origine du canal thoracique, dans l'abdomen","Au canal lymphatique droit","À un ganglion","À la rate"],"r":0,"e":"Le canal thoracique se jette dans la veine sous-clavière gauche et draine les trois quarts du corps.","s":6},{"q":"Les trois facteurs de compression assurant la circulation lymphatique sont :","o":["La contraction des muscles squelettiques voisins, celle des muscles lisses des parois lymphatiques et les variations de pression intrathoracique","Le cœur, les artères et les veines","La gravité seule","Les valves seules"],"r":0,"e":"La lymphe n'a pas de pompe propre ; les valves empêchent seulement le reflux.","s":6},{"q":"Les tissus lymphatiques contiennent :","o":["Lymphocytes, macrophages, cellules réticulaires et fibres réticulaires capturant micro-organismes et particules","Des érythrocytes","Des adipocytes seuls","Des fibroblastes seuls"],"r":0,"e":"Cette composition est commune au tissu diffus, aux ganglions, aux amygdales, à la rate et au thymus.","s":6},{"q":"L'amygdale pharyngée, ou végétation adénoïde, se situe :","o":["À la jonction de la cavité nasale et du pharynx","À la jonction de la cavité buccale et du pharynx","À la partie postérieure de la langue","Sous la muqueuse œsophagienne"],"r":0,"e":"Les amygdales palatines occupent la jonction buccale et les linguales la partie postérieure de la langue.","s":6},{"q":"Les ganglions lymphatiques se situent :","o":["Dans le tissu adipeux, à proximité des vaisseaux sanguins, le long des vaisseaux lymphatiques","Dans les muscles","Dans les os","Dans la peau uniquement"],"r":0,"e":"Ils filtrent la lymphe et constituent le lieu où les lymphocytes s'agglutinent et exercent leurs fonctions.","s":6},{"q":"Les ganglions thoraciques sont au nombre d'environ :","o":["30","70","100","230"],"r":2,"e":"Les abdomino-pelviens sont environ 230, les cervicaux 70, les axillaires 30 et les inguino-poplités 20, pour un total d'environ 450.","s":6},{"q":"Les ganglions axillaires drainent :","o":["Les membres supérieurs et la surface thoracique","La tête et le cou","Les membres inférieurs","L'abdomen"],"r":0,"e":"Ils sont environ 30 ; les inguinaux et poplités, environ 20, drainent les membres inférieurs et le bassin superficiel.","s":6},{"q":"Les ganglions superficiels se situent :","o":["Dans l'hypoderme","Dans les muscles","Le long de l'aorte","Dans le médiastin"],"r":0,"e":"Les ganglions profonds sont, eux, répartis dans l'ensemble du corps.","s":6},{"q":"La rate a une taille comparable :","o":["À un poing fermé","À une amande","À une noix","À un pamplemousse"],"r":0,"e":"Elle détruit les érythrocytes vieillis, filtre le sang et constitue un réservoir sanguin limité.","s":6},{"q":"La diminution du volume splénique à l'effort a pour conséquence :","o":["Une augmentation des érythrocytes circulants et donc de l'apport d'oxygène aux muscles","Une baisse de l'hématocrite","Une vasodilatation","Une anémie"],"r":0,"e":"Ce volume peut diminuer de 40 à 50 % pendant l'effort.","s":6},{"q":"Le thymus est une glande :","o":["Bilobée","Unilobée","Trilobée","Diffuse"],"r":0,"e":"Il croît pendant la première année de vie, reste stable, puis involue vers 60 ans.","s":6},{"q":"À 40 ans, le tissu thymique est :","o":["En majeure partie remplacé par du tissu adipeux","Intact","Hypertrophié","Totalement disparu"],"r":0,"e":"Le thymus reste le lieu de maturation des lymphocytes T.","s":6},{"q":"L'éléphantiasis est dû :","o":["À un nématode transmis par les moustiques, obstruant les vaisseaux lymphatiques","À une bactérie","À un virus","À une carence"],"r":0,"e":"Il en résulte un œdème massif, souvent des extrémités.","s":6},{"q":"Parmi les composantes de l'immunité innée, le cours cite :","o":["Barrières cutanéo-muqueuses, phagocytes, inflammation, fièvre, complément et cellules NK","Les lymphocytes B","Les anticorps","Les lymphocytes T"],"r":0,"e":"L'immunité adaptative repose sur les lymphocytes B, humorale, et T, cellulaire.","s":6},{"q":"L'absorption des graisses par le système lymphatique se fait :","o":["Par les chylifères de l'intestin grêle, qui acheminent les lipides vers le système veineux","Par les ganglions","Par la rate","Par le thymus"],"r":0,"e":"C'est l'une des trois fonctions du système lymphatique, avec l'équilibre hydrique et la défense immunitaire.","s":6},{"q":"Les vaisseaux lymphatiques sont absents :","o":["Du système nerveux central, de la moelle osseuse et des tissus non vascularisés comme cartilages, épiderme et cornée","Du derme","Du muscle","De l'intestin"],"r":0,"e":"Ils sont présents dans pratiquement tous les autres tissus.","s":6},{"q":"La défense immunitaire du système lymphatique repose sur :","o":["La filtration de la lymphe par les ganglions et du sang par la rate, plus l'activité des lymphocytes et macrophages","La seule filtration ganglionnaire","La seule rate","Les seuls anticorps"],"r":0,"e":"Ces deux filtres complémentaires couvrent le compartiment interstitiel et le compartiment sanguin.","s":6},{"q":"Lequel n'est PAS une fonction du système respiratoire ?","o":["Échanges gazeux","Contrôle du pH sanguin","Phonation","Production d'érythrocytes"],"r":3,"e":"Les érythrocytes sont produits par la moelle osseuse. Le système respiratoire assure échanges gazeux, pH, phonation, odorat, protection.","s":7},{"q":"Les voies aériennes inférieures comprennent :","o":["Nez et pharynx","Larynx, trachée, bronches, poumons","Bouche et œsophage","Cavité nasale uniquement"],"r":1,"e":"Voies inférieures = larynx, trachée, bronches, bronchioles, poumons. Supérieures = nez, cavité nasale, pharynx.","s":7},{"q":"Lors de l'inspiration :","o":["Palv > PA","Palv = PA","Palv < PA","Aucun flux"],"r":2,"e":"À l'inspiration : Palv < PA → l'air entre dans les poumons.","s":7},{"q":"Lors de l'expiration calme :","o":["Le diaphragme se contracte","Le diaphragme se relâche, rétraction élastique","Palv = PA","Le volume thoracique augmente"],"r":1,"e":"Expiration calme = relâchement du diaphragme + rétraction élastique → ↓ volume thoracique → Palv > PA.","s":7},{"q":"La pression pleurale à la fin d'une expiration normale est d'environ :","o":["+5 cm H₂O","0 cm H₂O","-5 cm H₂O","-20 cm H₂O"],"r":2,"e":"Ppl ≈ -5 cm H₂O à la fin de l'expiration calme (effet de succion par rétraction élastique).","s":7},{"q":"Le surfactant pulmonaire :","o":["Augmente la tension superficielle","Diminue la tension superficielle","Cause des œdèmes","Bloque les bronches"],"r":1,"e":"Le surfactant diminue la tension superficielle de la pellicule de liquide alvéolaire → empêche le collapsus.","s":7},{"q":"La compliance pulmonaire mesure :","o":["Le volume résiduel","La facilité avec laquelle les poumons se dilatent","La FR","La saturation en O₂"],"r":1,"e":"Compliance = ΔV/ΔP : volume gagné par unité de pression alvéolaire.","s":7},{"q":"Le volume courant (VT) au repos est d'environ :","o":["100 mL","500 mL","1500 mL","3000 mL"],"r":1,"e":"VT ≈ 500 mL au repos.","s":7},{"q":"Le volume résiduel correspond à :","o":["L'air inspirable supplémentaire","L'air restant après une expiration forcée maximale","Le volume courant","La capacité vitale"],"r":1,"e":"Volume résiduel ≈ 1200 mL : il reste toujours dans les poumons même après expiration forcée.","s":7},{"q":"La capacité vitale (CV) correspond à :","o":["VRI + VT","VRI + VT + VRE","VT + VR","Toutes les capacités"],"r":1,"e":"CV = VRI + VT + VRE ≈ 4600 mL : volume max expirable après une inspiration forcée.","s":7},{"q":"La capacité pulmonaire totale (CPT) est d'environ :","o":["2300 mL","4600 mL","5800 mL","10 000 mL"],"r":2,"e":"CPT = VRI + VT + VRE + VR ≈ 5800 mL.","s":7},{"q":"La ventilation totale est calculée par :","o":["FR × VT","FR + VT","VT / FR","VT × VR"],"r":0,"e":"Ventilation totale = FR × VT (litres/min).","s":7},{"q":"La ventilation alvéolaire est calculée par :","o":["FR × VT","FR × (VT - VEM)","VT × VEM","FR × CPT"],"r":1,"e":"Ventilation alvéolaire = FR × (VT - VEM) : volume disponible pour les échanges.","s":7},{"q":"L'espace mort anatomique comprend :","o":["Les alvéoles uniquement","Les voies de conduction (nez à bronchioles terminales)","Le poumon entier","Les capillaires pulmonaires"],"r":1,"e":"Espace mort anatomique = zones de conduction sans échange gazeux (du nez aux bronchioles terminales).","s":7},{"q":"Lequel ne favorise PAS la diffusion à travers la membrane respiratoire ?","o":["Surface importante","Membrane fine","Faible gradient de pression partielle","Bon coefficient de diffusion"],"r":2,"e":"Un faible gradient diminue la diffusion. Les facteurs favorables : grande surface, membrane fine, fort gradient, bon coefficient.","s":7},{"q":"La majeure partie de l'O₂ est transportée :","o":["Dissoute dans le plasma","Liée à l'hémoglobine","Sous forme de bicarbonate","Liée à l'albumine"],"r":1,"e":"L'essentiel de l'O₂ est lié à l'hémoglobine (oxyhémoglobine) ; seule une petite fraction est dissoute.","s":7},{"q":"L'effet Bohr décrit :","o":["Baisse d'affinité Hb-O₂ avec ↓ pH","Augmentation d'affinité Hb-O₂ avec ↑ pH","Pas d'effet du pH","Une seule action à 37 °C"],"r":0,"e":"Effet Bohr : ↑ H⁺ (↓ pH) → ↓ affinité Hb-O₂ → libération d'O₂ aux tissus actifs.","s":7},{"q":"Le 2,3-BPG :","o":["Augmente l'affinité Hb-O₂","Diminue l'affinité Hb-O₂ → meilleure libération aux tissus","Bloque la diffusion","Lie le CO₂"],"r":1,"e":"Le 2,3-BPG diminue l'affinité de l'Hb pour l'O₂ → favorise la libération aux tissus.","s":7},{"q":"L'hémoglobine fœtale (HbF) :","o":["Est moins concentrée que l'Hb maternelle","Est plus affine pour l'O₂ que l'Hb maternelle","Est identique à l'Hb adulte","Est sensible au 2,3-BPG"],"r":1,"e":"HbF est plus affine pour l'O₂, peu sensible au 2,3-BPG, et bénéficie d'un double effet Bohr → transfert d'O₂ de la mère au fœtus.","s":7},{"q":"Quelle est la principale forme de transport du CO₂ ?","o":["Dissous dans le plasma (7 %)","Lié aux protéines (23 %)","Bicarbonate HCO₃⁻ (70 %)","Lié à l'O₂"],"r":2,"e":"~ 70 % du CO₂ est transporté sous forme de bicarbonate HCO₃⁻ ; 23 % carbaminés ; 7 % dissous.","s":7},{"q":"L'effet Haldane :","o":["Hb désoxygénée fixe plus facilement le CO₂","Hb oxygénée fixe plus de CO₂","Le CO₂ se dissout uniquement","Effet inverse du Bohr sur le CO₂"],"r":0,"e":"Effet Haldane : Hb qui a libéré son O₂ se lie plus facilement au CO₂. Couplé à l'effet Bohr.","s":7},{"q":"Une augmentation du CO₂ sanguin :","o":["Augmente le pH","Diminue le pH","N'a pas d'effet sur le pH","Augmente le pH puis le diminue"],"r":1,"e":"↑ CO₂ → ↑ H₂CO₃ → ↑ H⁺ → ↓ pH (acidose). Le système respiratoire régule le pH via la ventilation.","s":7},{"q":"La dérivation du chlore (shift chlorure) se produit :","o":["Dans le plasma","Dans les érythrocytes","Dans les alvéoles","Dans les neurones"],"r":1,"e":"Dans les érythrocytes : CO₂ + H₂O → HCO₃⁻ qui sort en échange de Cl⁻ entrant.","s":7},{"q":"L'unité de pression utilisée en physiologie respiratoire est souvent :","o":["Pascal","cm H₂O","Atmosphère","Bar"],"r":1,"e":"En physiologie respiratoire, les faibles pressions sont exprimées en cm H₂O (1 cm H₂O = 0,74 cm Hg).","s":7},{"q":"La rétraction pulmonaire est due à :","o":["Aux muscles squelettiques uniquement","Aux fibres élastiques + tension superficielle des alvéoles","Au cœur","Au diaphragme uniquement"],"r":1,"e":"Rétraction = fibres élastiques des parois alvéolaires + tension superficielle du film de liquide alvéolaire (modulée par le surfactant).","s":7},{"q":"Le surfactant pulmonaire est sécrété par :","o":["Les pneumocytes de type I","Les pneumocytes de type II","Les macrophages alvéolaires","Les cellules endothéliales capillaires"],"r":1,"e":"Les pneumocytes II, cubiques et minoritaires en surface, produisent ce film phospholipidique et servent aussi de cellules souches de l'épithélium alvéolaire. Les pneumocytes I, très étalés, tapissent 95 % de la surface et assurent les échanges gazeux. La synthèse devient efficace vers 34 semaines de gestation.","s":7},{"q":"Le muscle principal de l'inspiration au repos est :","o":["Les intercostaux internes","Le diaphragme","Le sternocléidomastoïdien","Les abdominaux"],"r":1,"e":"Diaphragme (~75 % du travail inspiratoire au repos), aidé par les intercostaux externes.","s":7},{"q":"La majorité de l'O₂ dans le sang est transportée :","o":["Dissoute dans le plasma","Liée à l'hémoglobine","Sous forme de carbonate","Liée à l'albumine"],"r":1,"e":"≈ 98,5 % de l'O₂ est transporté par l'hémoglobine (HbO₂) ; 1,5 % dissous dans le plasma.","s":7},{"q":"La majorité du CO₂ dans le sang est transportée sous forme :","o":["Dissoute","De bicarbonates (HCO₃⁻)","Liée à l'Hb","Gazeuse"],"r":1,"e":"≈ 70 % sous forme de HCO₃⁻ (transformation par l'anhydrase carbonique des GR), 23 % lié à l'Hb (carbamino-Hb), 7 % dissous.","s":7},{"q":"Les centres respiratoires bulbaires sont principalement stimulés par :","o":["Une baisse de la PaO₂, détectée par les chémorécepteurs centraux","Une hausse de la PaCO₂, via les H⁺ produits dans le liquide céphalo-rachidien","Une baisse de la température corporelle","Une hausse de la pression artérielle"],"r":1,"e":"Le CO₂ franchit la barrière hémato-encéphalique, s'hydrate en H₂CO₃ et libère des H⁺ que détectent les chémorécepteurs centraux : c'est le stimulus dominant de la ventilation. L'hypoxie n'agit que par les chémorécepteurs périphériques (glomus carotidiens et aortiques), et seulement en dessous d'environ 60 mmHg.","s":7},{"q":"Parmi les fonctions du système respiratoire, le cours cite :","o":["Le contrôle du pH sanguin via la modulation du CO₂","La production d'hormones","La filtration du sang","La thermorégulation seule"],"r":0,"e":"S'y ajoutent les échanges gazeux, la phonation, l'odorat et la protection contre les micro-organismes.","s":7},{"q":"Les quatre étapes de la respiration sont :","o":["Ventilation, diffusion ou respiration externe, transport des gaz, échanges gazeux tissulaires ou respiration interne","Inspiration et expiration seules","Diffusion et transport","Ventilation et perfusion"],"r":0,"e":"La respiration externe se fait au niveau alvéolaire, la respiration interne au niveau des tissus.","s":7},{"q":"L'unité de pression utilisée en physiologie respiratoire est :","o":["Le centimètre d'eau, sachant que 1 cm H₂O vaut 0,74 cm Hg","Le millimètre de mercure seul","Le pascal","Le bar"],"r":0,"e":"La pression atmosphérique sert de référence à 0.","s":7},{"q":"À la fin de l'inspiration :","o":["La pression alvéolaire égale la pression atmosphérique et le flux s'arrête","La pression alvéolaire dépasse l'atmosphérique","L'air continue d'entrer","L'air sort"],"r":0,"e":"Pendant l'inspiration, la pression atmosphérique dépasse l'alvéolaire, ce qui fait entrer l'air.","s":7},{"q":"La rétraction pulmonaire résulte :","o":["De la rétraction élastique des fibres des parois alvéolaires et de la tension superficielle du film liquidien","Des seuls muscles","De la seule pression pleurale","Du seul surfactant"],"r":0,"e":"Le surfactant diminue précisément cette tension superficielle.","s":7},{"q":"À la fin d'une expiration normale, la pression pleurale est de :","o":["-5 cm H₂O, la pression alvéolaire étant à 0","0 cm H₂O","+5 cm H₂O","-10 cm H₂O"],"r":0,"e":"La pression pleurale reste inférieure à l'alvéolaire par effet de succion de la rétraction élastique.","s":7},{"q":"À l'inspiration, la pression pleurale diminue parce que :","o":["L'augmentation du volume thoracique abaisse la pression, et les poumons dilatés augmentent leur tendance à la rétraction, donc l'effet de succion","Les muscles se relâchent","Le surfactant augmente","La plèvre se décolle"],"r":0,"e":"Les poumons suivent le thorax par adhérence des plèvres.","s":7},{"q":"La compliance pulmonaire se calcule par :","o":["Le rapport de la variation de volume sur la variation de pression, en L par cm H₂O","Le produit volume × pression","Le rapport pression sur volume","La fréquence × le volume courant"],"r":0,"e":"Elle mesure la facilité avec laquelle poumons et thorax se dilatent.","s":7},{"q":"Le volume de réserve inspiratoire est d'environ :","o":["500 mL","1100 mL","1200 mL","3000 mL"],"r":3,"e":"Le volume courant vaut environ 500 mL, la réserve expiratoire 1100 mL et le volume résiduel 1200 mL.","s":7},{"q":"Le volume de réserve expiratoire est d'environ :","o":["500 mL","1100 mL","3000 mL","4600 mL"],"r":1,"e":"C'est l'air supplémentaire expirable après une expiration normale.","s":7},{"q":"La capacité inspiratoire est d'environ :","o":["2300 mL","3500 mL","4600 mL","5800 mL"],"r":1,"e":"Elle réunit le volume courant et la réserve inspiratoire.","s":7},{"q":"La capacité résiduelle fonctionnelle est d'environ :","o":["2300 mL, soit la réserve expiratoire plus le volume résiduel","3500 mL","4600 mL","1200 mL"],"r":0,"e":"La capacité vitale vaut environ 4600 mL et la capacité pulmonaire totale 5800 mL.","s":7},{"q":"La ventilation totale se calcule par :","o":["La fréquence respiratoire multipliée par le volume courant","La fréquence multipliée par la capacité vitale","Le volume courant moins l'espace mort","La fréquence divisée par le volume"],"r":0,"e":"La ventilation alvéolaire soustrait, elle, l'espace mort au volume courant avant de multiplier par la fréquence.","s":7},{"q":"L'espace mort physiologique comprend :","o":["L'espace mort anatomique plus les alvéoles non fonctionnels","L'espace anatomique seul","Les seules alvéoles","Les bronchioles terminales seules"],"r":0,"e":"L'espace mort anatomique regroupe les zones de conduction, des cavités nasales aux bronchioles terminales.","s":7},{"q":"Parmi les facteurs influençant la diffusion à travers la membrane respiratoire, le cours cite :","o":["L'épaisseur de la membrane, le coefficient de diffusion du gaz, la surface fonctionnelle et le gradient de pression partielle","La seule surface","Le seul gradient","La fréquence respiratoire"],"r":0,"e":"Une diminution d'épaisseur augmente la diffusion.","s":7},{"q":"Le coefficient de diffusion d'un gaz est approximativement :","o":["Celui qu'il a dans l'eau","Celui qu'il a dans l'air","Nul","Identique pour tous les gaz"],"r":0,"e":"C'est l'un des quatre facteurs influençant la diffusion alvéolo-capillaire.","s":7},{"q":"La courbe de dissociation de l'oxyhémoglobine est :","o":["Sigmoïdale","Linéaire","Hyperbolique","En cloche"],"r":0,"e":"Une augmentation de la pression partielle en oxygène augmente la saturation de l'hémoglobine.","s":7},{"q":"L'effet Bohr correspond au fait que :","o":["Une augmentation des ions H⁺, donc une baisse de pH, diminue l'affinité de l'hémoglobine pour l'oxygène","Une baisse de pH augmente l'affinité","Le CO₂ n'a aucun effet","La température n'a aucun effet"],"r":0,"e":"Une augmentation de la PCO₂ et de la température agit dans le même sens, libérant l'oxygène aux tissus actifs.","s":7},{"q":"L'hémoglobine fœtale se caractérise par :","o":["Une concentration environ 50 % supérieure à celle de la mère et une structure différente","Une concentration inférieure","Une structure identique","Une forte sensibilité au 2,3-BPG"],"r":0,"e":"Le 2,3-BPG a peu d'effet sur elle, et le double effet Bohr facilite le transfert d'oxygène de la mère au fœtus.","s":7},{"q":"Une augmentation du 2,3-bisphosphoglycérate :","o":["Diminue l'affinité de l'hémoglobine pour l'oxygène et améliore sa libération aux tissus","Augmente l'affinité","Est sans effet","Bloque le transport"],"r":0,"e":"C'est l'un des quatre facteurs modulant la courbe de dissociation de l'oxyhémoglobine.","s":7}]};
